/* eslint-disable -- Generated by tools/convert-phase-two.mjs from the original visualization. */
import C from './scenario.js';
import * as ENG from './engine.js';
export function mountSandbox(root, renderPresetControls) {
  'use strict';
  let observer;
  const events = new AbortController();
  const listen = (node, event, fn) => node.addEventListener(event, fn, { signal: events.signal });

  /* ---------- helpers ---------- */
  const $ = id => root.querySelector('#' + id);
  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const pad = n => String(n).padStart(2, '0');
  const clampInt = (v, lo, hi, d) => { v = Math.round(Number(v)); if (!Number.isFinite(v)) return d; return Math.max(lo, Math.min(hi, v)); };
  const textW = (s, size) => { let w = 0; for (const ch of String(s)) w += ch.charCodeAt(0) > 0x2e7f ? size : size * 0.58; return w; };
  const CN = ['零','一','两','三','四','五','六','七','八'];
  const DEF = C.defaults, NAMES = C.teamNames, MACHINE = C.machineName || 'EdgePod';
  const TYPES = Object.fromEntries(C.riskTypes.map(x => [x.type, x]));
  const STAGE = {pre: '赛前', in: '赛中', post: '赛后'};
  const ICONS = new Set(['infra','dr','ppt','fa','generic']);
  const TASKS = (C.tasks || []).slice(0, 8).map((x, i) => ({...x, slot: i + 1, icon: ICONS.has(x.icon) ? x.icon : 'generic'}));
  const T1 = TASKS.filter(x => x.phase === 1), T2 = TASKS.filter(x => x.phase !== 1);
  const TBY = Object.fromEntries(TASKS.map(x => [x.id, x]));
  const PH = C.phases;
  const list = arr => arr.map(x => x.en).join('、');
  const tchip = (x, cls = '') => `<span class="tchip t-${esc(x.id)} ${cls}"><svg><use href="#i-${x.icon}"/></svg></span>`;
  const ico = (name, cls = '') => `<span class="ic ${cls}"><svg><use href="#i-${name}"/></svg></span>`;
  const reduced = window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches;
  const rnHTML = n => { const r = R.risks[n - 1]; return `<span class="rn ${r ? r.def.sev : ''}">#${n}</span>`; };
  const shortLabel = s => String(s).split(/：| · |（| → /)[0];

  /* ---------- params ---------- */
  const FIELDS = [
    {g: '赛制', k: 'start', label: '开赛日期（原定）', help: '推演假设，官网未公布', type: 'date'},
    {g: '赛制', k: 'hour', label: '开赛时刻', help: '预案建议 09:00', type: 'hour'},
    {g: '赛制', k: 'teams', label: '队伍数', help: '官网：首届 5 队', type: 'num', min: 1, max: 8},
    {g: '赛制', k: 'window', label: '每队窗口（小时）', help: '官网：168 小时', type: 'num', min: 24, max: 720, step: 6},
    {g: '赛制', k: 'phase1', label: '第一阶段（小时）', help: '官网：0–30 小时', type: 'num', min: 1, max: 700},
    {g: '赛制', k: 'sealAt', label: '封存点（第几小时）', help: 'V1.3 参考：第 120 小时', type: 'num', min: 2, max: 719, step: 6},
    {g: '赛前', k: 'prepStart', label: '准备开始', help: '默认今天', type: 'date'},
    {g: '赛前', k: 'edgepodArrive', label: 'EdgePod 到位', help: '假设已在现场', type: 'date'},
    {g: '赛前', k: 'scope', label: 'Benchmark 范围', help: '最低可用版见预案 §2.4', type: 'seg', options: [['mvp', '最低可用'], ['full', '完整版']]},
    {g: '赛前', k: 'launch', label: '开赛策略', help: '预案建议按启动门禁', type: 'seg', options: [['gate', '按门禁'], ['fixed', '硬开']]},
    {g: '赛前', k: 'practiceLead', label: '练习期（天）', help: '开赛前至少开放几天', type: 'num', min: 0, max: 30},
    {g: '预案', k: 'gap', label: '换队间隔（小时）', help: '预案建议 24 小时', type: 'num', min: 0, max: 168, step: 6},
    {g: '预案', k: 'handover', label: '交接耗时（小时）', help: '估计 7–15 小时', type: 'num', min: 1, max: 96},
    {g: '预案', k: 'makeupDays', label: '补赛窗口（天）', help: '最后一队之后的缓冲', type: 'num', min: 0, max: 14},
    {g: '预案', k: 'standby', label: '候补队', help: '预案建议 2 支', type: 'num', min: 0, max: 2},
    {g: '预案', k: 'holidayPlan', label: '节假日方案', help: '保障不了就节前停赛', type: 'seg', options: [['keep', '照常比'], ['pause', '节前停赛']]},
    {g: '预案', k: 'noMakeupMax', label: '不补时上限（小时）', help: '累计不超过就不补', type: 'num', min: 0, max: 24},
    {g: '预案', k: 'moveOver', label: '挪补赛阈值（小时）', help: '单次宕机超过就挪', type: 'num', min: 2, max: 168, step: 6}
  ];
  const FBY = Object.fromEntries(FIELDS.map(f => [f.k, f]));
  const validDate = s => ENG.isoUTC(s) != null;
  function clampP(p){
    const q = {...p};
    ['start', 'prepStart', 'edgepodArrive'].forEach(k => { if (!validDate(q[k])) q[k] = DEF[k]; });
    q.hour = clampInt(q.hour, 0, 23, DEF.hour);
    q.teams = clampInt(q.teams, 1, Math.min(8, NAMES.length - 2), DEF.teams);
    q.window = clampInt(q.window, 24, 720, DEF.window);
    q.phase1 = clampInt(q.phase1, 1, q.window - 2, Math.min(DEF.phase1, q.window - 2));
    q.sealAt = clampInt(q.sealAt, q.phase1 + 1, q.window - 1, Math.min(Math.max(DEF.sealAt, q.phase1 + 1), q.window - 1));
    q.practiceLead = clampInt(q.practiceLead, 0, 30, DEF.practiceLead);
    q.gap = clampInt(q.gap, 0, 168, DEF.gap);
    q.handover = clampInt(q.handover, 1, 96, DEF.handover);
    q.makeupDays = clampInt(q.makeupDays, 0, 14, DEF.makeupDays);
    q.standby = clampInt(q.standby, 0, 2, DEF.standby);
    q.noMakeupMax = clampInt(q.noMakeupMax, 0, 24, DEF.noMakeupMax);
    q.moveOver = clampInt(q.moveOver, 2, 168, DEF.moveOver);
    if (!['mvp', 'full'].includes(q.scope)) q.scope = DEF.scope;
    if (!['gate', 'fixed'].includes(q.launch)) q.launch = DEF.launch;
    if (!['keep', 'pause'].includes(q.holidayPlan)) q.holidayPlan = DEF.holidayPlan;
    q.dur = {...(p.dur || {})};
    return q;
  }

  /* ---------- state ---------- */
  let P = clampP({...DEF});
  let risks = [], uid = 0, presetId = 'clean';
  let R = null, B = null;
  let view = 'pre', t = 0, sel = 0, logFilter = 'all';
  let playing = false, raf = 0, curLog = -2;
  let GX = null;

  /* ---------- params panel ---------- */
  (function buildParams(){
    const groups = [['赛制', '每队的窗口和阶段'], ['赛前', '准备的假设'], ['预案', '换队、补时和节假日的规则']];
    $('pcards').innerHTML = groups.map(([g, sub]) => `<div class="card"><div class="card-h"><h3>${esc(g)}</h3><p>${esc(sub)}</p></div>${FIELDS.filter(f => f.g === g).map(f => {
      let c;
      if (f.type === 'date') c = `<input class="inp" type="date" data-k="${f.k}" aria-label="${esc(f.label)}">`;
      else if (f.type === 'hour') c = `<select class="inp" data-k="${f.k}" aria-label="${esc(f.label)}">${Array.from({length: 24}, (_, h) => `<option value="${h}">${pad(h)}:00</option>`).join('')}</select>`;
      else if (f.type === 'seg') c = `<div class="segc" data-k="${f.k}" role="group" aria-label="${esc(f.label)}">${f.options.map(o => `<button type="button" data-v="${o[0]}">${esc(o[1])}</button>`).join('')}</div>`;
      else c = `<div class="stepper" data-k="${f.k}"><button type="button" data-d="-1" aria-label="减少">−</button><input type="number" data-k="${f.k}" min="${f.min}" max="${f.max}" step="${f.step || 1}" inputmode="numeric" aria-label="${esc(f.label)}"><button type="button" data-d="1" aria-label="增加">+</button></div>`;
      return `<div class="pr"><div><b>${esc(f.label)}</b><small>${esc(f.help)}</small></div>${c}</div>`;
    }).join('')}</div>`).join('');
    const setK = (k, v) => { stop(); const np = {...P}; np[k] = v; if (k === 'scope') np.dur = {}; P = clampP(np); recompute(); syncInputs(); };
    listen($('pcards'), 'click', e => {
      const sb = e.target.closest('.segc[data-k] button'); if (sb){ setK(sb.parentElement.dataset.k, sb.dataset.v); return; }
      const st = e.target.closest('.stepper button'); if (st){ const k = st.parentElement.dataset.k, f = FBY[k]; setK(k, P[k] + (+st.dataset.d) * (f.step || 1)); }
    });
    listen($('pcards'), 'change', e => {
      const el = e.target.closest('[data-k]'); if (!el || el.classList.contains('segc') || el.classList.contains('stepper')) return;
      const f = FBY[el.dataset.k]; if (!f) return;
      if (el.value === '' && f.type === 'num'){ syncInputs(); return; }
      setK(f.k, f.type === 'num' || f.type === 'hour' ? Number(el.value) : el.value);
    });
  })();
  function syncInputs(){
    FIELDS.forEach(f => {
      if (f.type === 'seg') $('pcards').querySelectorAll(`.segc[data-k="${f.k}"] button`).forEach(b => b.setAttribute('aria-pressed', String(b.dataset.v === P[f.k])));
      else { const el = $('pcards').querySelector(`input[data-k="${f.k}"],select[data-k="${f.k}"]`); if (el && document.activeElement !== el) el.value = P[f.k]; }
    });
    $('literal').setAttribute('aria-pressed', String(Object.entries(C.literal || {}).every(([k, v]) => P[k] === v)));
  }
  listen($('reset'), 'click', () => { stop(); P = clampP({...DEF}); risks = []; presetId = 'clean'; recompute(); syncInputs(); });
  listen($('literal'), 'click', () => { stop(); P = clampP({...P, ...(C.literal || {})}); recompute(); syncInputs(); });

  /* ---------- risks ---------- */
  const mkRisk = (type, vals) => { const d = TYPES[type]; const r = {uid: ++uid, type}; d.fields.forEach(f => { r[f.k] = vals && vals[f.k] != null ? vals[f.k] : f.def; }); return r; };
  function loadPreset(id){ const p = C.presets.find(x => x.id === id); if (!p) return; presetId = id; risks = p.risks.map(r => mkRisk(r.type, r)); }
  function dice(){
    const pick = arr => arr[Math.floor(Math.random() * arr.length)];
    const by = s => C.riskTypes.filter(x => x.stage === s);
    const chosen = [pick(by('pre')), pick(by('in')), pick(by('in')), pick(by('post'))];
    if (Math.random() < .5) chosen.push(pick(C.riskTypes));
    const seen = new Set();
    risks = chosen.filter(d => { if (seen.has(d.type) && d.type !== 'outage') return false; seen.add(d.type); return true; }).map(d => {
      const v = {};
      d.fields.forEach(f => {
        if (f.type === 'team') v[f.k] = NAMES[Math.floor(Math.random() * P.teams)];
        else if (f.type === 'sel') v[f.k] = pick(f.options)[0];
        else { const hi = f.k === 'at' ? P.window - 1 : Math.min(f.max, Math.max(f.def * 2, f.min + 1)); const lo = f.k === 'at' ? 1 : Math.max(f.min, Math.round(f.def / 2)); v[f.k] = Math.round(lo + Math.random() * (hi - lo)); }
      });
      return mkRisk(d.type, v);
    });
    presetId = '__dice';
  }
  const presetName = () => { const p = C.presets.find(x => x.id === presetId); return p ? p.name : presetId === '__dice' ? '随机' : '自定义'; };
  function renderPresets(){
    const p = C.presets.find(x => x.id === presetId);
    renderPresetControls({ presets: C.presets, presetId, riskCount: risks.length, description: p ? p.desc : presetId === '__dice' ? '随机抽了几件事，赛前、赛中、赛后各至少一件。再掷一次换一组。' : '自定义组合。', choose: onPreset });
    $('topPreset').innerHTML = C.presets.map(p => `<option value="${esc(p.id)}" ${p.id === presetId ? 'selected' : ''}>${esc(p.name)}</option>`).join('') + (C.presets.some(p => p.id === presetId) ? '' : `<option value="" selected>${esc(presetName())}</option>`);
    const hit = R.risks.filter(r => r.status === 'hit').length;
    $('scenBox').innerHTML = `<span>当前情景</span><b>${esc(presetName())}</b><span>${risks.length ? `${risks.length} 条风险 · ${hit} 条触发` : '没有注入风险'}</span>`;
  }
  const onPreset = id => { stop(); if (id === '__clear'){ risks = []; presetId = 'clean'; } else if (id === '__dice') dice(); else loadPreset(id); recompute(); };
  listen($('topPreset'), 'change', e => { if (e.target.value) onPreset(e.target.value); });
  listen($('topDice'), 'click', () => onPreset('__dice'));
  (function buildAdd(){
    $('radd').innerHTML = `<option value="">添加一条风险…</option>` + ['pre', 'in', 'post'].map(s => `<optgroup label="${STAGE[s]}">${C.riskTypes.filter(x => x.stage === s).map(x => `<option value="${esc(x.type)}">${esc(x.name)}</option>`).join('')}</optgroup>`).join('');
    listen($('radd'), 'change', e => { const v = e.target.value; e.target.value = ''; if (!v) return; stop(); risks.push(mkRisk(v)); presetId = '__custom'; recompute(); });
  })();
  function fieldCtl(r, f){
    const name = `${r.uid}:${f.k}`;
    if (f.type === 'team'){ const opts = NAMES.slice(0, P.teams); if (!opts.includes(r[f.k])) opts.push(r[f.k]); return `<label>${esc(f.label)}<select data-r="${name}">${opts.map(L => `<option value="${esc(L)}" ${L === r[f.k] ? 'selected' : ''}>${esc(L)} 队</option>`).join('')}</select></label>`; }
    if (f.type === 'sel') return `<label>${esc(f.label || '')}<select data-r="${name}">${f.options.map(o => `<option value="${esc(o[0])}" ${o[0] === r[f.k] ? 'selected' : ''}>${esc(o[1])}</option>`).join('')}</select></label>`;
    return `<label>${esc(f.label)}<input type="number" data-r="${name}" min="${f.min}" max="${f.max}" value="${esc(r[f.k])}">${esc(f.unit || '')}</label>`;
  }
  function renderRisks(){
    renderPresets();
    if (!risks.length){ $('rlist').innerHTML = `<p class="empty">还没有注入风险，现在看到的是预案本身的节奏。</p>`; $('raddNote').textContent = ''; return; }
    $('rlist').innerHTML = risks.map((r, i) => {
      const d = TYPES[r.type], rr = R.risks[i] || {};
      const st = rr.status === 'dead' ? `<span class="tag">未生效</span>` : rr.status === 'hit' ? `<span class="tag ${d.sev === 'critical' ? 'crit' : 'warn'}"><i></i>已触发</span>` : `<span class="tag">没有触发</span>`;
      const eff = rr.status === 'dead' ? esc(rr.effect) : rr.status === 'hit' ? `<b>${esc(rr.effect)}</b>${rr.h != null ? ` · ${esc(fT(rr.h))}` : ''}` : '';
      return `<div class="rr${rr.status === 'dead' ? ' dead' : ''}">
        <span class="ic ${d.sev === 'critical' ? 'crit' : 'warn'}" style="font:600 11px var(--fm)">#${i + 1}</span>
        <div><div class="ttl"><b>${esc(d.name)}</b><span>${STAGE[d.stage]} · 预案 ${esc(d.ref)}</span></div>
          ${d.fields.length ? `<div class="rk-f">${d.fields.map(f => fieldCtl(r, f)).join('')}</div>` : ''}
          ${eff ? `<p class="eff">${eff}</p>` : ''}</div>
        <div class="side-r">${st}<button class="xbtn" type="button" data-x="${r.uid}" aria-label="删除这条风险"><svg><use href="#i-x"/></svg></button></div>
      </div>`;
    }).join('');
    $('raddNote').textContent = `共 ${risks.length} 条`;
  }
  listen($('rlist'), 'change', e => {
    const el = e.target.closest('[data-r]'); if (!el) return;
    const [u, k] = el.dataset.r.split(':'); const r = risks.find(x => x.uid === +u); if (!r) return;
    const f = TYPES[r.type].fields.find(x => x.k === k);
    r[k] = f.type === 'num' ? clampInt(el.value, f.min, f.max, f.def) : el.value;
    presetId = '__custom'; stop(); recompute();
  });
  listen($('rlist'), 'click', e => { const b = e.target.closest('[data-x]'); if (!b) return; risks = risks.filter(x => x.uid !== +b.dataset.x); presetId = risks.length ? '__custom' : 'clean'; stop(); recompute(); });

  /* ---------- simulate ---------- */
  function recompute(){
    const lst = risks.map(({uid, ...r}) => r);
    try { R = ENG.simulate(C, P, lst); B = lst.length ? ENG.simulate(C, P, []) : R; }
    catch (err){ $('h1').textContent = `推演出错：${err.message}`; console.error(err); return; }
    const [L0, L1] = life(); t = Math.max(L0, Math.min(L1, t));
    if (sel >= R.event.slots.length) sel = 0;
    renderAll();
  }
  const life = () => [R.stages[0].a, R.stages[2].b];
  const evEnd = () => Math.max(R.stages[1].b, R.event.mkB || 0, ...R.event.mk.map(m => m.ho.b));
  function domainOf(v){ const s = R.stages; if (v === 'pre') return [s[0].a - 12, s[0].b + 30]; if (v === 'in') return [s[1].a, Math.max(evEnd(), s[1].a + 24)]; return [s[2].a - 12, s[2].b + 12]; }
  const stageOf = h => h < R.stages[1].a ? 'pre' : h < R.stages[1].b ? 'in' : 'post';
  const fT = h => stageOf(h) === 'in' ? R.F.dt(h) : R.F.day(h);
  function todayH(){ const d = new Date(); return (Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) - R.T0) / 3600e3 + d.getHours(); }
  function clockOf(sl, h){ if (h >= sl.e) return sl.quit ? sl.quit.at : sl.moved ? sl.moved.from : P.window; let lo = 0, hi = P.window; for (let i = 0; i < 22; i++){ const m = (lo + hi) / 2; if (sl.wall(m) <= h) lo = m; else hi = m; } return Math.floor(lo); }
  const bigDate = (h, withHour) => { const d = R.F.D(h); return `${d.getUTCMonth() + 1}月${d.getUTCDate()}日${withHour ? `<sup>${pad(d.getUTCHours())}:00</sup>` : ''}`; };
  const dd = (cur, base) => { if (!risks.length || cur == null || base == null || Math.abs(cur - base) < 1) return ''; return `<span class="tag warn">比无风险${cur > base ? '晚' : '早'} ${esc(R.F.dur(Math.abs(cur - base)))}</span>`; };

  /* ---------- overview ---------- */
  function renderOverview(){
    const F = R.F, M = R.metrics, BM = B.metrics, s = R.stages;
    const dPre = Math.round((s[0].b - s[0].a) / 24), dIn = Math.round((s[1].b - s[1].a) / 24);
    $('eyebrow').textContent = C.eyebrow || C.name;
    $('h1').innerHTML = `${P.teams === 1 ? '一支队伍' : `${CN[P.teams]}支队伍`}，一台 ${esc(MACHINE)}。<br><span>赛前 ${dPre} 天，比赛 ${dIn} 天，再加赛后 90 天。</span>`;
    const chip = M.slip > 0 ? `<span class="tag warn"><i></i>比原定晚 ${esc(F.dur(M.slip))}</span>` : M.unfinished ? `<span class="tag warn"><i></i>按期，${M.unfinished} 项没做完</span>` : `<span class="tag good"><i></i>按原定日期</span>`;
    $('hero').innerHTML = `<div class="lbl">开赛</div><div class="big">${bigDate(M.start, true)}</div>
      <div class="row">${chip}${dd(M.start, BM.start)}<span>原定 ${esc(F.dt(M.planned))} · ${P.launch === 'gate' ? '按启动门禁' : '按日期硬开'}</span></div>
      <div class="split">
        <div><span class="lbl">启动门禁</span><b>${esc(F.day(M.gateReady))}</b></div>
        <div><span class="lbl">全部完赛</span><b>${esc(F.day(M.eventEnd))}</b></div>
        <div><span class="lbl">赛后第 90 天</span><b>${esc(F.day(M.day90 - 24))}</b></div>
      </div>`;
    const hol = R.holidays.filter(x => x.h + 12 >= M.start && x.h + 12 < M.eventEnd).map(x => { const on = R.event.played.find(sl => x.h + 12 >= sl.s && x.h + 12 < sl.e); return `${x.name}${on ? `落在 ${on.who} 队窗口` : '时机器空闲'}`; });
    const rows = [
      ['flag', M.slip > 0 || M.unfinished ? 'warn' : 'good', M.slip > 0 ? `启动门禁 ${F.day(M.gateReady)} 才满足` : M.unfinished ? `硬开，${M.unfinished} 项准备没做完` : '启动门禁按时满足',
        `卡住开赛的是这条线：${M.critTxt}。`],
      ['infra', M.over > 0 ? 'warn' : 'acc', `${R.event.played.length} 队 ${F.day(M.start)} – ${F.day(M.eventEnd)} 依次独占 ${MACHINE}`,
        `${hol.length ? hol.join('，') + '。' : ''}${M.over > 0 ? `比公布的赛程晚 ${F.dur(M.over)}结束。` : '按公布的赛程结束。'}`],
      ['check', M.prizeExt ? 'warn' : 'acc', `${M.announce != null ? F.day(M.announce) : '—'} 公布成绩，${M.prize != null ? F.day(M.prize) : '—'} 奖金到账`,
        M.prizeExt ? `奖金发放撞上春节，顺延 ${F.days(M.prizeExt)}。` : '赛后流程顺利。'],
      ['alert', risks.length ? (R.disputes.some(d => d.star) ? 'crit' : 'warn') : '', risks.length ? `注入 ${risks.length} 条风险，${M.riskHit} 条触发` : '还没有注入风险',
        risks.length ? `引出 ${R.disputes.length} 类可能的争执${M.riskDead ? `；${M.riskDead} 条没生效` : ''}。` : '在“情景与风险”里选一个情景，或者在顶栏掷骰子。']
    ];
    $('findings').innerHTML = rows.map(r => `<div class="fr">${ico(r[0], r[1])}<div><b>${esc(r[2])}</b><p>${esc(r[3])}</p></div></div>`).join('');
    const day = h => `赛后第 ${Math.floor((h - M.dayOne) / 24) + 1} 天`;
    const st = [
      ['全部完赛', esc(F.day(M.eventEnd)), M.over > 0 ? `比公布晚 ${esc(F.dur(M.over))}` : '按公布的赛程', dd(M.eventEnd, BM.eventEnd)],
      ['比赛', `${dIn}<small>天</small>`, `${R.event.played.length} 队 × ${P.window} 小时`, ''],
      ['公布成绩', M.announce != null ? esc(F.day(M.announce)) : '—', M.announce != null ? day(M.announce) : '', dd(M.announce, BM.announce)],
      ['奖金到账', M.prize != null ? esc(F.day(M.prize)) : '—', M.prizeExt ? `遇春节顺延 ${esc(F.days(M.prizeExt))}` : M.prize != null ? day(M.prize) : '', dd(M.prize, BM.prize)],
      ['补时 / 作废', `${M.makeupH}<small>/ ${M.voidH + M.emptyH} 小时</small>`, [M.delayedN ? `${M.delayedN} 队晚开表` : '', M.movedN ? `${M.movedN} 队补赛` : '', M.standbyN ? `${M.standbyN} 支候补` : ''].filter(Boolean).join(' · ') || '没有补时和空档', ''],
      ['可能的争执', `${R.disputes.length}<small>类</small>`, R.disputes.some(x => x.star) ? `★ ${R.disputes.filter(x => x.star).length} 类最容易闹大` : R.disputes.length ? '预案 §5' : '没有', '']
    ];
    $('stats').innerHTML = st.map(x => `<div><span class="lbl">${x[0]}</span><b>${x[1]}</b><span class="sub">${x[2]}${x[3]}</span></div>`).join('');
    $('paramNote').textContent = '默认值是预案里的建议值（还没拍板），写在同目录的 scenario.js。整数参数用 − / + 调，二选一的直接点。“官网字面口径” = 00:00 开赛、换队不留间隔。';
  }

  /* ---------- life strip ---------- */
  function lifeSegs(){ const s = R.stages, pb = R.post.bands; return [{v: 'pre', cls: 'pre', a: s[0].a, b: s[0].b}, {v: 'in', cls: 'in', a: s[1].a, b: s[1].b}, ...pb.map((b, i) => ({v: 'post', cls: ['p1', 'p2', 'p3'][i] || 'p3', a: b.a, b: b.b}))]; }
  const lp = h => { const [L0, L1] = life(); return (h - L0) / (L1 - L0) * 100; };
  function renderLife(){
    const F = R.F, M = R.metrics, [L0, L1] = life();
    let s = lifeSegs().map(sg => `<span class="sg ${sg.cls}${sg.v === view ? ' on' : ''}" data-v="${sg.v}" style="left:${lp(sg.a)}%;width:calc(${lp(sg.b) - lp(sg.a)}% - 3px)"></span>`).join('');
    R.holidays.concat(R.blackout ? [{h: R.blackout.a, len: R.blackout.b - R.blackout.a}] : []).forEach(x => { if (x.h >= L0 && x.h <= L1) s += `<span class="hol" style="left:${lp(x.h)}%;width:${Math.max(.3, (x.len || 24) / (L1 - L0) * 100)}%"></span>`; });
    const placed = [];
    R.flags.forEach(f => { if (f.h < L0 || f.h > L1) return; let p = lp(f.h); while (placed.some(q => Math.abs(q - p) < 1.8)) p += 1.8; placed.push(p); s += `<span class="dot ${f.sev}" style="left:${p}%" title="#${f.n} ${esc(f.title)}">${f.n}</span>`; });
    // 月份刻度
    for (let d = Math.ceil(L0 / 24) * 24; d < L1; d += 24){ const dt = F.D(d); if (dt.getUTCDate() === 1) s += `<span class="ax" style="left:${lp(d)}%">${dt.getUTCFullYear() !== F.y0 ? dt.getUTCFullYear() + '/' : ''}${dt.getUTCMonth() + 1}月</span>`; }
    const th = todayH(); if (th >= L0 && th <= L1) s += `<span class="today" style="left:${lp(th)}%" title="今天"></span>`;
    s += `<span class="ph" id="lifePh" style="left:${lp(t)}%"></span>`;
    $('strip').innerHTML = s;
    $('lifeNote').textContent = `${F.day(L0)} → ${F.day(L1 - 24)} · 点或拖这条带子跳到任一时刻`;
    const hol = (a, b) => R.holidays.filter(x => x.h < b && x.h + 24 > a);
    const holN = (a, b) => { const h = hol(a, b); return h.length ? ` <span class="hn">经过${esc(h.map(x => `${x.name} ${F.day(x.h)}`).join('、'))}。</span>` : ''; };
    const cnt = st => R.flags.filter(f => stageOf(f.h) === st).length;
    const rn = st => cnt(st) ? ` ${cnt(st)} 条风险。` : '';
    const pb = R.post.bands;
    const items = [
      {cls: 'pre', name: '赛前准备', when: `${F.day(R.stages[0].a)} – ${F.day(M.start - 1)}`, note: `${Math.round((M.start - R.stages[0].a) / 24)} 天，启动门禁 ${F.day(M.gateReady)} 满足。${rn('pre')}`, x: ''},
      {cls: 'in', name: `比赛 · ${R.event.played.length} 队`, when: `${F.day(M.start)} – ${F.day(M.eventEnd - 1)}`, note: `${F.dur(M.eventEnd - M.start)}。${rn('in')}`, x: holN(M.start, M.eventEnd)},
      ...(C.postEvent || []).map((pe, i) => ({cls: ['p1', 'p2', 'p3'][i], name: pe.name, when: `${F.day(pb[i].a)} – ${F.day(pb[i].b - 24)}`, note: (i === 0 && M.announce != null ? `${F.day(M.announce)} 公布成绩。` : i === 1 && M.prize != null ? `${F.day(M.prize)} 奖金到账。` : '') + (i === 0 ? rn('post') : ''), x: holN(pb[i].a, pb[i].b) + `<br>${esc(pe.note)}`}))
    ];
    $('legs').innerHTML = items.map(it => `<li><span class="sw sg ${it.cls}" style="position:static"></span><b>${esc(it.name)}</b><span class="when">${esc(it.when)}</span><p>${esc(it.note)}${it.x}</p></li>`).join('');
  }
  function placeLifePh(){ const el = $('lifePh'); if (el) el.style.left = lp(t) + '%'; $('strip').querySelectorAll('.sg').forEach(sg => sg.classList.toggle('on', sg.dataset.v === view)); }
  (function lifePointer(){
    const el = $('strip'); let drag = false;
    const go = e => { const rc = el.getBoundingClientRect(); const f = Math.max(0, Math.min(1, (e.clientX - rc.left) / rc.width)); const [L0, L1] = life(); stop(); setT(L0 + f * (L1 - L0), true); };
    listen(el, 'pointerdown', e => { if (e.button !== 0) return; drag = true; el.setPointerCapture(e.pointerId); go(e); });
    listen(el, 'pointermove', e => { if (drag) go(e); });
    listen(el, 'pointerup', () => { drag = false; });
  })();

  /* ---------- timeline ---------- */
  function renderVTabs(){
    const s = R.stages;
    const v = [['pre', '赛前', `${Math.round((s[0].b - s[0].a) / 24)} 天`], ['in', '赛中', `${Math.round((s[1].b - s[1].a) / 24)} 天`], ['post', '赛后', '90 天']];
    $('vtabs').innerHTML = v.map(x => `<button type="button" data-v="${x[0]}" aria-pressed="${view === x[0]}">${x[1]}<small>${esc(x[2])}</small></button>`).join('');
    $('crumbStage').textContent = STAGE[view];
  }
  listen($('vtabs'), 'click', e => {
    const b = e.target.closest('button[data-v]'); if (!b) return;
    stop(); view = b.dataset.v;
    const [a, z] = domainOf(view); if (t < a || t > z) t = R.stages.find(x => x.id === view).a;
    renderVTabs(); renderBoard(); renderTime();
  });
  const sk = (w, h) => `<svg class="k" viewBox="0 0 24 12" aria-hidden="true">${w}</svg>`;
  function renderBoard(){
    if (view === 'in'){
      $('tlTitle').textContent = `${MACHINE} 上机日历`;
      $('tlSub').textContent = `每行一队，窗口 ${P.window} 小时，分三段：第一阶段 ${P.phase1} 小时、开发期、第 ${P.sealAt} 小时封存后的正式评测。已经比完的部分是靛紫，没比的是灰色轨道。`;
      $('tlNote').textContent = '红块是宕机，点状条是换队交接，橙色虚框是比公布时间晚开表的部分，窗口下的细条是评审。';
      $('legend').innerHTML = [
        [sk(`<rect x="0" y="2" width="8" height="8" rx="2" fill="var(--acc-1)"/><rect x="8.5" y="2" width="8" height="8" rx="2" fill="var(--acc)"/><rect x="17" y="2" width="7" height="8" rx="2" fill="var(--acc-2)"/>`), '第一阶段 · 开发期 · 正式评测'],
        [sk(`<rect x="0" y="2" width="24" height="8" rx="3" fill="var(--track)"/>`), '还没比'],
        [sk(`<rect x="0" y="1" width="24" height="10" rx="2" fill="var(--crit)"/>`), '宕机'],
        [sk(`<rect x="0" y="3" width="24" height="6" rx="2" fill="url(#pt-dots)"/>`), '交接'],
        [sk(`<rect x="1" y="1" width="22" height="10" rx="3" fill="none" stroke="var(--warn)" stroke-width="1.5" stroke-dasharray="4 3"/>`), '晚开表'],
        [sk(`<rect x="0" y="1" width="24" height="10" rx="2" fill="url(#pt-hatch)"/>`), '作废'],
        [sk(`<rect x="0" y="0" width="24" height="12" fill="var(--hol)"/>`), '节假日'],
        ...TASKS.map(x => [tchip(x), x.en])
      ].map(x => `<li>${x[0]}${esc(x[1])}</li>`).join('');
      renderEvent();
    } else {
      const pre = view === 'pre';
      $('tlTitle').textContent = pre ? '赛前：从准备开始到开赛' : '赛后：算分、复现、公布，再到 90 天计划';
      $('tlSub').textContent = pre ? '每行一条工作线。靛紫是关键路径，也就是决定启动门禁时间的那条链；其余是灰色。竖线标出原定开赛、门禁满足和实际开赛。' : '从最后一队下机算赛后第 1 天。复现要用机器，算分要等复现，公布要等 7 天异议期；奖金发放遇到春节会顺延。';
      $('tlNote').textContent = pre ? '工期是估计值，在“赛前任务表”里可以改。' : '赛后步骤都从早上开工。';
      $('legend').innerHTML = [
        [sk(`<rect x="0" y="2" width="24" height="8" rx="3" fill="var(--acc)"/>`), '关键路径'],
        [sk(`<rect x="0" y="2" width="24" height="8" rx="3" fill="var(--bar)"/>`), '任务'],
        [sk(`<rect x="1" y="2" width="22" height="8" rx="3" fill="var(--bar)" stroke="var(--crit)" stroke-width="1.5"/>`), '受风险影响'],
        ...(pre ? [[sk(`<rect x="1" y="2" width="22" height="8" rx="3" fill="var(--bar)" stroke="var(--warn)" stroke-width="1.5" stroke-dasharray="4 2"/>`), '开赛时没做完']] : []),
        [sk(`<circle cx="12" cy="6" r="4" fill="var(--ink)"/>`), '节点'],
        [sk(`<rect x="0" y="0" width="24" height="12" fill="var(--hol)"/>`), '节假日'],
        [sk(`<line x1="12" y1="0" x2="12" y2="12" stroke="var(--acc)" stroke-dasharray="3 2" stroke-width="1.5"/>`), '今天']
      ].map(x => `<li>${x[0]}${esc(x[1])}</li>`).join('');
      renderLanes(view);
    }
  }

  function axis(X, A, Z, top, yb, opt){
    const F = R.F, pxDay = (X(A + 24) - X(A));
    let s = '';
    const hols = R.holidays.map(x => ({a: x.h, b: x.h + 24, name: x.name, d: F.day(x.h)}));
    if (R.blackout) hols.push({a: R.blackout.a, b: R.blackout.b, name: R.blackout.name, d: ''});
    hols.forEach(x => {
      const a = Math.max(A, x.a), b = Math.min(Z, x.b); if (b <= a) return;
      s += `<rect class="hol" x="${X(a)}" y="${top - 6}" width="${X(b) - X(a)}" height="${yb - top + 6}"/>`;
      if (R.blackout && x.name !== R.blackout.name && x.a >= R.blackout.a && x.a < R.blackout.b) return;
      s += `<text class="hol-t" x="${(X(a) + X(b)) / 2}" y="${yb + 16}" text-anchor="middle">${esc(x.name)}${x.d ? ' ' + esc(x.d) : ''}</text>`;
    });
    const step = [1, 2, 7, 14].find(v => pxDay * v >= 24) || 28;
    const months = [];
    for (let d = Math.floor(A / 24) * 24, j = 0; d < Z; d += 24, j++){
      const dt = F.D(d), first = dt.getUTCDate() === 1, a = Math.max(A, d), b = Math.min(Z, d + 24);
      const mon = dt.getUTCDay() === 1;
      if (d > A && (first || (pxDay >= 10 && (step === 1 || mon)))) s += `<line class="grid${first ? ' mo' : ''}" x1="${X(d)}" x2="${X(d)}" y1="${top - 6}" y2="${yb}"/>`;
      if (step === 1){ if (X(b) - X(a) >= 14) s += `<text class="t-d" x="${(X(a) + X(b)) / 2}" y="${top - 14}" text-anchor="middle">${dt.getUTCDate()}</text>`; }
      else if (d >= A && mon && (step <= 7 || Math.floor(d / 168) % 2 === 0) && X(d) + 14 < X(Z)) s += `<text class="t-d" x="${X(d) + 3}" y="${top - 14}">${dt.getUTCDate()}</text>`;
      if (first && d > A) months.push({x: X(d), d: dt});
    }
    const all = [{x: X(A), d: F.D(A)}, ...months];
    if (all.length > 1 && all[1].x - all[0].x < 70) all.shift();
    let lastX = -999;
    all.forEach(mo => { if (mo.x - lastX < 70 || mo.x > X(Z) - 30) return; const y = mo.d.getUTCFullYear(); s += `<text class="t-m" x="${mo.x + 3}" y="${top - 32}">${y !== F.y0 ? y + '年' : ''}${mo.d.getUTCMonth() + 1}月</text>`; lastX = mo.x; });
    if (opt && opt.today){ const th = todayH(); if (th >= A && th <= Z) s += `<line class="today" x1="${X(th)}" x2="${X(th)}" y1="${top - 6}" y2="${yb}"/><text class="today-t" x="${X(th) + 4}" y="${yb - 5}">今天</text>`; }
    return s;
  }
  function playheadSVG(){
    if (!GX || t < GX.A || t > GX.Z) return '';
    const px = GX.X(t), lab = fT(t), lw = Math.max(64, textW(lab, 11) + 16), lx = Math.min(Math.max(px - lw / 2, 4), GX.W - lw - 2);
    return `<line class="phl" x1="${px}" x2="${px}" y1="${GX.top - 8}" y2="${GX.yb + 2}"/><circle class="phk" cx="${px}" cy="${GX.top - 8}" r="4.5"/><rect class="php" x="${lx}" y="${GX.yb + 24}" width="${lw}" height="20" rx="10"/><text class="pht" x="${lx + lw / 2}" y="${GX.yb + 38}" text-anchor="middle">${esc(lab)}</text>`;
  }
  function drawPlayhead(){ const layer = root.querySelector('#' + 'phLayer'); if (layer) layer.innerHTML = playheadSVG(); }

  function slotState(sl){
    if (sl.kind === 'empty') return {k: 'empty', pill: '空档', cls: 'wait'};
    if (t < sl.s) return {k: 'wait', pill: '等待', cls: 'wait'};
    const out = sl.outs.find(o => t >= o.a && t < o.b);
    if (out && t < Math.max(sl.e, out.b)) return {k: 'out', pill: '宕机', cls: 'alarm', out};
    if (t < sl.e){ const k = sl.seal != null && t >= sl.seal ? 'formal' : sl.p1 != null && t >= sl.p1 ? 'dev' : 'p1'; return {k, pill: k === 'p1' ? PH[0].name : k === 'dev' ? '开发期' : '正式评测', cls: 'active'}; }
    const m = R.event.mk.find(x => x.sl === sl);
    if (m && t < m.a) return {k: 'mkwait', pill: '等补赛', cls: 'wait'};
    if (m && t < m.b) return {k: 'mk', pill: '补赛', cls: 'active'};
    if (sl.quit) return {k: 'quit', pill: '已退出', cls: 'done'};
    return {k: 'done', pill: '完成', cls: 'done'};
  }

  /* ---- 赛中：每队一行，进度条式窗口 ---- */
  function renderEvent(){
    const F = R.F, ev = R.event, slots = ev.slots, n = slots.length;
    const [A, Z] = domainOf('in');
    const W = 1060, L = 168, RR = 20, top = 62, rowH = 66, bh = 26;
    const plotW = W - L - RR, k = plotW / (Z - A), X = h => L + (Math.max(A, Math.min(Z, h)) - A) * k;
    const yb = top + n * rowH, H = yb + 52;
    GX = {X, A, Z, top, yb, W, H, L, rowH, kind: 'in'};
    let s = `<svg class="gantt" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(`${MACHINE} 上机日历：` + slots.map(x => x.kind === 'empty' ? `${x.L} 队空档` : `${x.who} 队 ${F.dt(x.s)} 至 ${F.dt(x.e)}`).join('；'))}">`;
    slots.forEach((sl, i) => { if (i === sel) s += `<rect class="rowsel" x="0" y="${top + i * rowH - 4}" width="${W}" height="${rowH}" rx="8"/>`; });
    if (ev.pause){ const a = Math.max(A, ev.pause[0]), b = Math.min(Z, ev.pause[1]); if (b > a) s += `<rect class="pz" x="${X(a)}" y="${top - 6}" width="${X(b) - X(a)}" height="${yb - top + 6}"/><text class="cap" x="${X(a) + 6}" y="${yb - 6}">节前停赛</text>`; }
    if (P.makeupDays > 0){ const a = Math.max(A, ev.mkA), b = Math.min(Z, ev.mkB); if (b > a) s += `<rect class="rsv" x="${X(a)}" y="${top - 6}" width="${X(b) - X(a)}" height="${yb - top + 6}" rx="8"/><text class="cap" x="${X(a) + 6}" y="${yb - 6}">补赛窗口 ${P.makeupDays} 天</text>`; }
    s += axis(X, A, Z, top, yb, {});
    const segs = sl => {
      const p1 = sl.p1 != null ? sl.p1 : sl.e, se = sl.seal != null ? sl.seal : sl.e;
      return [[sl.s, p1, 1, PH[0].name.replace('第一阶段', 'Infra')], [p1, se, 2, '开发'], [se, sl.e, 3, '评测']].filter(x => x[1] > x[0]);
    };
    const badges = [];
    slots.forEach((sl, i) => {
      const st = slotState(sl), y = top + i * rowH, by = y + 6, cy = by + bh / 2;
      // 左侧：头像 + 名字 + 状态
      const on = st.cls === 'active', alarm = st.cls === 'alarm';
      s += `<g data-tip="${esc(`${sl.who} 队${sl.kind === 'standby' ? `（候补，接 ${sl.L} 队）` : ''}\n${sl.kind === 'empty' ? '赛前退出，空档' : `${F.dt(sl.s)} → ${F.dt(sl.e)}`}`)}"><circle cx="30" cy="${cy}" r="15" class="av${on ? ' on' : ''}" style="${alarm ? 'fill:var(--crit);stroke:var(--crit)' : ''}"/><text class="av-t" x="30" y="${cy + 4.5}" text-anchor="middle" style="${on || alarm ? 'fill:#fff' : ''}">${esc(sl.who)}</text>`;
      s += `<text class="nm" x="54" y="${cy - 2}">${esc(sl.who)} ${sl.kind === 'standby' ? '候补' : '队'}</text><text class="nm-s" x="54" y="${cy + 13}">${esc(st.pill)}</text></g>`;
      // 交接（上一队下机后），画在本行
      const pv = slots.slice(0, i).reverse().find(x => x.ho);
      if (pv && sl.kind !== 'empty'){
        const ho = pv.ho, hx = X(ho.a), hw = X(ho.b) - hx;
        if (hw > 2) s += `<rect class="ho" x="${hx + 1}" y="${cy - 4}" width="${hw - 2}" height="8" rx="4" data-tip="${esc(`换队交接（${pv.who} 队下机后）${ho.extra ? ` · 重装失败多花 ${ho.extra} 小时` : ''}\n${F.dt(ho.a)} → ${F.dt(ho.b)}（${F.dur(ho.b - ho.a)}）\n${C.handover}`)}"/>`;
        if (ho.b > sl.ann){ const ox = X(Math.max(ho.a, sl.ann)); if (X(ho.b) - ox > 1) s += `<rect class="over" x="${ox}" y="${cy - 4}" width="${X(ho.b) - ox}" height="8" rx="4" pointer-events="none"/>`; }
      }
      if (sl.kind === 'empty'){
        const x1 = X(sl.s), w = X(sl.e) - x1;
        s += `<rect class="emp" x="${x1}" y="${by}" width="${w}" height="${bh}" rx="8" data-tip="${esc(`${sl.L} 队赛前退出，候补没补上\n${F.dt(sl.s)} → ${F.dt(sl.e)}\n空档作缓冲，后面的队不提前。`)}"/>`;
        if (w > 150) s += `<text class="sm" x="${x1 + 12}" y="${cy + 4}">${esc(sl.L)} 队退出 · 空档作缓冲</text>`;
        return;
      }
      if (sl.delay > 0){ const gx = X(sl.ann), gw = X(sl.s) - gx; if (gw > 2) s += `<rect class="ghost" x="${gx}" y="${by}" width="${gw}" height="${bh}" rx="8" data-tip="${esc(`公布的上机时间 ${F.dt(sl.ann)}\n实际 ${F.dt(sl.s)}，晚 ${F.dur(sl.delay)}`)}"/>`; }
      // 三段：轨道 + 已经过去的部分
      segs(sl).forEach(([a, b, ph, name], j, arr) => {
        const x0 = X(a) + (j ? 1.5 : 0), x1 = X(b) - (j < arr.length - 1 ? 1.5 : 0), w = Math.max(1, x1 - x0);
        const tip = ph === 1 ? `${sl.who} 队 · ${PH[0].name}（开卷）\n${list(T1)}\n${F.dt(a)} → ${F.dt(b)}` : ph === 2 ? `${sl.who} 队 · 开发期\n${list(T2)} 全部必做\n${F.dt(a)} → ${F.dt(b)}` : `${sl.who} 队 · 正式评测（组委会运行，断网）\n第 ${P.sealAt} 小时封存后\n${F.dt(a)} → ${F.dt(b)}${sl.makeup ? `\n含补时 ${sl.makeup} 小时` : ''}`;
        s += `<rect class="trk" x="${x0}" y="${by}" width="${w}" height="${bh}" rx="${j === 0 ? 8 : 3}" data-tip="${esc(tip)}"/>`;
        const done = t >= b, nowIn = t > a && t < b;
        if (done || nowIn){ const ex = done ? x1 : X(t); s += `<rect class="el${ph}" x="${x0}" y="${by}" width="${Math.max(0, ex - x0)}" height="${bh}" rx="${j === 0 ? 8 : 3}" pointer-events="none"/>`; }
        const lab = ph === 1 ? (T1[0] ? 'Infra' : '') : name;
        const cw = ph === 1 ? T1.length * 20 + 6 : ph === 2 ? T2.length * 20 + 6 : 0;
        if (w > cw + textW(lab, 10.5) + 14){
          const lx = x0 + 8 + cw, filled = t >= a + (lx + textW(lab, 10.5) - x0) / k;
          s += `<text class="seg-t ${filled ? (ph === 3 ? 'w3' : 'w') : 'm'}" x="${lx}" y="${cy + 3.8}">${esc(lab)}</text>`;
        }
        const tl = ph === 1 ? T1 : ph === 2 ? T2 : [];
        if (tl.length && w >= tl.length * 20 + 8) tl.forEach((tk, q) => { s += `<g data-tip="${esc(`${tk.en}（${tk.zh}）· ${tk.points} 分`)}"><rect x="${x0 + 5 + q * 20}" y="${cy - 8}" width="16" height="16" rx="4" fill="var(--t-${tk.id}-bg)"/><use href="#i-${tk.icon}" x="${x0 + 8 + q * 20}" y="${cy - 5}" width="10" height="10" style="color:var(--t-${tk.id})"/></g>`; });
      });
      sl.outs.forEach(o => {
        const ox = X(o.a), ow = X(o.b) - ox; if (ow <= 0) return;
        const c = o.cause === 'degraded' ? 'out deg' : (o.comp || o.move) ? 'out' : 'out soft';
        s += `<rect class="${c}" x="${ox}" y="${by}" width="${Math.max(2.5, ow)}" height="${bh}" rx="3" data-tip="${esc(`#${o.n} 第 ${o.at} 小时宕机 ${o.hours} 小时（${o.cause === 'platform' ? '平台故障' : o.cause === 'team' ? '队伍自己弄崩' : '部分故障，降配继续'}）\n${o.move ? '剩余时间挪到补赛窗口' : o.comp ? '停表，补等长时间' : o.cause === 'degraded' ? '不停表，成绩标“条件不一致”' : '不补时'}`)}"/>`;
      });
      if (sl.makeup && X(sl.e) < W - 60) s += `<text class="sm" x="${X(sl.e) + 6}" y="${cy + 4}">补 ${sl.makeup}h</text>`;
      if (sl.quit){ const vx = X(sl.e), vw = X(sl.s + P.window) - vx; if (vw > 2){ s += `<rect class="void" x="${vx + 1.5}" y="${by}" width="${vw - 1.5}" height="${bh}" rx="3" data-tip="${esc(`${sl.who} 队第 ${sl.quit.at} 小时退出\n剩余 ${sl.quit.voidH} 小时作废，作缓冲`)}"/>`; if (vw > 70) s += `<text class="sm" x="${vx + 10}" y="${cy + 4}">作废 ${sl.quit.voidH}h</text>`; } }
      const m = ev.mk.find(x => x.sl === sl);
      if (m){
        const rx = X(m.ra), ax = X(m.a), bx = X(m.b);
        if (ax - rx > 1) s += `<rect class="mkr" x="${rx}" y="${cy - 4}" width="${ax - rx}" height="8" rx="4" data-tip="${esc(`${sl.who} 队补赛前从归档恢复现场\n${F.dt(m.ra)} → ${F.dt(m.a)}`)}"/>`;
        if (bx - ax > 1){
          s += `<rect class="trk" x="${ax + 1}" y="${by}" width="${bx - ax - 1}" height="${bh}" rx="8"/>`;
          if (t > m.a) s += `<rect class="el2" x="${ax + 1}" y="${by}" width="${Math.max(0, X(Math.min(t, m.b)) - ax - 1)}" height="${bh}" rx="8" pointer-events="none"/>`;
          s += `<rect class="mk" x="${ax + 1}" y="${by}" width="${bx - ax - 1}" height="${bh}" rx="8" data-tip="${esc(`${sl.who} 队补赛：剩余 ${sl.moved.remain} 小时\n${F.dt(m.a)} → ${F.dt(m.b)}${m.b > ev.mkB ? '\n超出补赛窗口' : ''}`)}"/>`;
          if (bx - ax > 50) s += `<text class="seg-t ${t > m.a + 30 / k ? 'w' : 'm'}" x="${ax + 10}" y="${cy + 3.8}">补赛</text>`;
        }
      }
      const rv = R.items.find(it => it.id === `review:${sl.L}`);
      if (rv && rv.a < Z){ const ra = X(rv.a), rb = X(Math.min(rv.b, Z)); if (rb - ra > 2) s += `<rect class="rv${(rv.cls || []).includes('late') ? ' late' : ''}" x="${ra + 2}" y="${by + bh + 6}" width="${rb - ra - 2}" height="4" rx="2" data-tip="${esc(rv.tip)}"/>`; }
      const lab = `${F.dt(sl.s)}${sl.delay > 0 ? ` · 晚 ${F.dur(sl.delay)}` : ''}`;
      const x1 = X(sl.s);
      s += `<text class="t-d" x="${x1 + 2}" y="${by + bh + 22}">${esc(lab)}</text>`;
      R.flags.filter(f => f.team && (f.type === 'handover_fail' ? (slots.slice(0, i).reverse().find(x => x.ho) || {}).L === f.team : f.team === sl.L)).forEach(f => badges.push({x: X(f.h), y: by - 3, f}));
    });
    const placed = [];
    badges.forEach(bd => { let x = bd.x; while (placed.some(p => p.y === bd.y && Math.abs(p.x - x) < 20)) x += 20; placed.push({x, y: bd.y}); s += `<g class="rb ${bd.f.sev}" data-tip="${esc(`#${bd.f.n} ${bd.f.title}\n${fT(bd.f.h)}`)}"><circle cx="${x}" cy="${bd.y}" r="8.5"/><text x="${x}" y="${bd.y + 3.3}" text-anchor="middle">${bd.f.n}</text></g>`; });
    s += `<g id="phLayer"></g></svg>`;
    $('ganttBox').innerHTML = s;
    drawPlayhead();
  }

  /* ---- 赛前 / 赛后：分行图 ---- */
  const ROWICON = {pod: ['infra', 'acc'], base: ['base', ''], reg: ['rules', ''], ppl: ['people', ''], score: ['check', ''], svc: ['chat', ''], rules: ['shield', ''], money: ['money', ''], after: ['open', '']};
  function renderLanes(v){
    const F = R.F, rows = (C.views && C.views[v]) || [];
    const [A, Z] = domainOf(v);
    const W = 1060, L = 214, RR = 20;
    const plotW = W - L - RR, k = plotW / (Z - A), X = h => L + (Math.max(A, Math.min(Z, h)) - A) * k, pxDay = 24 * k;
    const byId = new Map(); R.items.forEach(it => { if (it.id) byId.set(it.id, it); });
    const M = R.metrics;
    const vm = v === 'pre'
      ? [M.start !== M.planned ? {h: M.planned, t: '原定开赛', c: 'ghost'} : null, {h: M.gateReady, t: '门禁满足', c: 'gate'}, {h: M.start, t: M.unfinished ? '开赛（硬开）' : '开赛', c: 'ink'}].filter(Boolean)
      : [{h: M.eventEnd, t: '全部完赛', c: 'ink'}, ...R.post.bands.slice(1).map(b => ({h: b.a, t: b.name.replace('赛后 ', '第 '), c: 'soft'}))];
    vm.sort((p, q) => p.h - q.h);
    const vmRows = []; vm.forEach(m => { const x = X(m.h), w = textW(m.t, 10.5) + 16; let r = 0; while (vmRows.some(q => q.r === r && x - w / 2 < q.x1 && x + w / 2 > q.x0)) r++; m.r = r; m.x = x; m.w = w; vmRows.push({r, x0: x - w / 2 - 4, x1: x + w / 2 + 4}); });
    const vmH = (Math.max(0, ...vm.map(m => m.r)) + 1) * 22;
    const top = 74 + vmH, tH = 28;
    const lay = []; let y = top;
    rows.forEach(row => {
      const its = row.ids.map(id => byId.get(id)).filter(it => it && (it.b != null ? it.b : it.a) >= A && it.a <= Z).sort((p, q) => p.a - q.a);
      const tracks = [];
      its.forEach(it => {
        let x0, x1; it._out = null; it._left = false;
        if (it.kind === 'ms'){ const lw = textW(it.label, 11) + 8; x0 = X(it.a) - 7; x1 = X(it.a) + 7 + lw; if (x1 > W - RR){ it._left = true; x0 = X(it.a) - 7 - lw; x1 = X(it.a) + 7; } }
        else { x0 = X(it.a); x1 = X(it.b); const w = x1 - x0 - 1, lab = shortLabel(it.label); if (w <= textW(lab, 11) + 14 && pxDay >= 8 && it.a >= A && x1 + 6 + textW(lab, 11) < W - RR){ it._out = lab; x1 += 8 + textW(lab, 11); } }
        let ti = tracks.findIndex(e => e + 4 <= x0); if (ti < 0){ ti = tracks.length; tracks.push(x1); } else tracks[ti] = x1;
        it._t = ti;
      });
      const h = Math.max(50, Math.max(1, tracks.length) * tH + 18);
      lay.push({row, y, h, its}); y += h;
    });
    const yb = y, H = yb + 52;
    GX = {X, A, Z, top, yb, W, H, L, kind: v};
    let s = `<svg class="gantt" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(`${STAGE[v]}分行图：${F.day(A)} 到 ${F.day(Z)}`)}">`;
    lay.forEach((r, i) => { if (i) s += `<line class="ln-sep" x1="10" x2="${W - 8}" y1="${r.y}" y2="${r.y}"/>`; });
    s += axis(X, A, Z, top, yb, {today: true});
    lay.forEach(r => {
      const row = r.row, cy = r.y + 25, tk = row.task ? TBY[row.task] : null;
      if (tk) s += `<rect x="12" y="${cy - 12}" width="24" height="24" rx="7" fill="var(--t-${tk.id}-bg)"/><use href="#i-${tk.icon}" x="17" y="${cy - 7}" width="14" height="14" style="color:var(--t-${tk.id})"/>`;
      else { const ic = ROWICON[row.id] || ['generic', '']; s += `<rect x="12" y="${cy - 12}" width="24" height="24" rx="7" fill="${ic[1] === 'acc' ? 'var(--acc-soft)' : 'var(--sunken)'}"/><use href="#i-${ic[0]}" x="17" y="${cy - 7}" width="14" height="14" style="color:${ic[1] === 'acc' ? 'var(--acc)' : 'var(--ink-2)'}"/>`; }
      s += `<text class="nm" x="46" y="${cy - 2}">${esc(tk ? tk.en : row.name)}</text><text class="nm-s" x="46" y="${cy + 13}">${esc(tk ? `${tk.zh} · 判定器` : row.sub || '')}</text>`;
    });
    vm.forEach(m => {
      if (m.h < A || m.h > Z) return;
      const py = 14 + m.r * 22;
      s += `<line class="vm ${m.c === 'ink' ? '' : m.c}" x1="${m.x}" x2="${m.x}" y1="${py + 9}" y2="${yb}"/><rect class="vmp ${m.c === 'ink' ? 'ink' : m.c === 'gate' ? 'gate' : ''}" x="${m.x - m.w / 2}" y="${py - 9}" width="${m.w}" height="18" rx="9"/><text class="vmt ${m.c === 'ink' ? 'ink' : m.c === 'gate' ? 'gate' : ''}" x="${m.x}" y="${py + 3.6}" text-anchor="middle">${esc(m.t)}</text>`;
    });
    lay.forEach(r => {
      r.its.forEach(it => {
        const y0 = r.y + 13 + it._t * tH, cls = it.cls || [], tip = esc(it.tip || it.label);
        if (it.kind === 'ms'){
          const x = X(it.a), cy = y0 + 10, mc = cls.includes('hit') ? 'hit' : cls.includes('late') ? 'late' : '';
          s += `<circle class="msd ${mc}" cx="${x}" cy="${cy}" r="5" data-tip="${tip}"/>`;
          s += it._left ? `<text class="mst" x="${x - 10}" y="${cy + 4}" text-anchor="end">${esc(it.label)}</text>` : `<text class="mst" x="${x + 10}" y="${cy + 4}">${esc(it.label)}</text>`;
          return;
        }
        const x0 = X(it.a), x1 = X(it.b), w = Math.max(2, x1 - x0 - 1);
        const kc = ['lb', ...cls.filter(c => ['crit', 'hit', 'late', 'ext', 'drop', 'cont'].includes(c))].join(' ');
        s += `<rect class="${kc}" x="${x0}" y="${y0}" width="${w}" height="20" rx="5" data-tip="${tip}"/>`;
        const lab = w > textW(it.label, 11) + 14 ? it.label : w > textW(shortLabel(it.label), 11) + 14 ? shortLabel(it.label) : null;
        const tc = cls.includes('crit') ? 'w' : '';
        if (cls.includes('drop')){ if (w > 64) s += `<text class="lt" x="${x0 + 7}" y="${y0 + 14}">没做完：${esc(shortLabel(it.label))}</text>`; }
        else if (lab) s += `<text class="lt ${tc}" x="${x0 + 7}" y="${y0 + 14}">${esc(lab)}</text>`;
        else if (it._out) s += `<text class="lt o" x="${x0 + w + 6}" y="${y0 + 14}">${esc(it._out)}</text>`;
      });
    });
    const rb = [];
    R.flags.filter(f => f.h >= A && f.h <= Z && stageOf(f.h) === v).forEach(f => { let x = X(f.h); while (rb.some(q => Math.abs(q - x) < 20)) x += 20; rb.push(x); s += `<g class="rb ${f.sev}" data-tip="${esc(`#${f.n} ${f.title}\n${fT(f.h)}`)}"><circle cx="${x}" cy="${top - 2}" r="8.5"/><text x="${x}" y="${top + 1.3}" text-anchor="middle">${f.n}</text></g>`; });
    s += `<g id="phLayer"></g></svg>`;
    $('ganttBox').innerHTML = s;
    drawPlayhead();
  }

  /* ---------- now + ledger ---------- */
  function machineAt(h){
    const ev = R.event, F = R.F;
    const sl = ev.played.find(x => h >= x.s && h < x.e);
    if (sl){
      const out = sl.outs.find(o => h >= o.a && h < o.b);
      const ph = sl.seal != null && h >= sl.seal ? '正式评测' : sl.p1 != null && h >= sl.p1 ? '开发期' : PH[0].name;
      return {tone: out ? 'crit' : 'acc', title: `${sl.who} 队 · ${ph}`, text: out ? `#${out.n} 宕机中，${out.comp ? '停表，补等长时间' : out.move ? '剩余时间挪到补赛窗口' : '不补时'}。` : ph === PH[0].name ? `${list(T1)} · 已用 ${clockOf(sl, h)} / ${P.phase1} 小时` : ph === '开发期' ? `${T2.length} 类应用并行 · ${F.dur(sl.seal - h)}后封存` : `组委会运行，断网考场 · ${F.dur(sl.e - h)}后下机`};
    }
    const out = ev.played.flatMap(x => x.outs.map(o => ({...o, who: x.who}))).find(o => h >= o.a && h < o.b);
    if (out) return {tone: 'crit', title: `${out.who} 队长时间宕机`, text: `#${out.n} 修复中，剩余时间挪到补赛窗口。`};
    const m = ev.mk.find(x => h >= x.ra && h < x.b);
    if (m) return {tone: 'acc', title: `${m.sl.who} 队补赛`, text: h < m.a ? '从归档恢复现场中。' : `补剩余的 ${m.sl.moved.remain} 小时，${F.dur(m.b - h)}后结束。`};
    const ho = ev.played.find(x => x.ho && h >= x.ho.a && h < x.ho.b);
    if (ho){ const nx = ev.slots.find(x => x.kind !== 'empty' && x.i > ho.i); return {tone: '', title: nx ? `换队交接：${ho.who} → ${nx.who}` : `${ho.who} 队下机后归档`, text: `${C.handover}。${nx ? `${F.dur(nx.s - h)}后 ${nx.who} 队上机。` : ''}`}; }
    const emp = ev.slots.find(x => x.kind === 'empty' && h >= x.s && h < x.e);
    if (emp) return {tone: 'warn', title: `${emp.L} 队的空档`, text: '赛前退出，候补没补上，作缓冲。'};
    const pt = R.prep.list.find(x => x.lane === 'pod' && x.durH > 0 && h >= x.es && h < x.ef && x.state !== 'drop');
    if (pt) return {tone: '', title: pt.name, text: pt.note || '赛前，机器上的准备。'};
    const qt = R.post.list.find(x => x.lane === 'pod' && h >= x.es && h < x.ef);
    if (qt) return {tone: '', title: qt.name, text: qt.note || ''};
    if (ev.pause && h >= ev.pause[0] && h < ev.pause[1]) return {tone: '', title: '节前停赛', text: '这段时间不排队伍。'};
    const acc = R.prep.list.find(x => x.id === 'pod_accept');
    if (acc && h < acc.es) return {tone: '', title: '还没到位', text: `${F.day(acc.es)} 到位验收。`};
    if (h >= R.stages[2].a) return {tone: '', title: '赛后空闲', text: '可以作 Testbed。'};
    return {tone: '', title: '空闲', text: h >= R.stages[1].a ? '等下一队上机。' : ''};
  }
  function renderNow(){
    const F = R.F, s = R.stages, M = R.metrics, ev = R.event, st = stageOf(t);
    const dayIdx = h0 => Math.floor((t - h0) / 24) + 1;
    const meta = st === 'pre' ? `赛前第 ${dayIdx(Math.floor(s[0].a / 24) * 24)} 天 · 距开赛 ${F.dur(M.start - t)}` : st === 'in' ? `开赛第 ${dayIdx(Math.floor(M.start / 24) * 24)} 天 · 第 ${Math.floor(t - M.start)} / ${Math.round(M.eventEnd - M.start)} 小时` : t >= s[2].b ? '赛后 90 天计划已走完' : `赛后第 ${dayIdx(M.dayOne)} 天 · ${(R.post.bands.find(b => t >= b.a && t < b.b) || {}).name || ''}`;
    const ms = machineAt(t);
    const lanes = Object.fromEntries((C.lanes || []).map(l => [l.id, l.name]));
    const work = R.items.filter(it => it.kind === 'bar' && it.lane !== 'pod' && !String(it.id || '').startsWith('review') && t >= it.a && t < it.b).map(i => [lanes[i.lane] || '', i.label]);
    const rv = R.items.filter(it => String(it.id || '').startsWith('review') && t >= it.a && t < it.b);
    if (rv.length) work.push(['评审与复现', rv.map(r => r.label).join('、')]);
    const nextMs = R.items.filter(it => it.kind === 'ms' && it.a > t && !(it.cls || []).includes('ghost')).sort((p, q) => p.a - q.a || ((q.cls || []).includes('key') - (p.cls || []).includes('key')))[0];
    const recent = R.log.filter(l => (l.kind === 'risk' || l.kind === 'warn' || l.kind === 'resp') && l.h <= t && l.h > t - 72).slice(-3);
    $('nowCard').innerHTML = `<div class="lbl">时间轴所在时刻 · ${STAGE[st]}</div>
      <div class="big">${bigDate(t, st === 'in')}</div>
      <div class="now-meta">${esc(meta)}</div>
      <div class="rows">
        <div class="r">${ico('infra', ms.tone)}<div><b>${esc(ms.title)}</b><p>${esc(ms.text)}</p></div><span class="tag">${esc(MACHINE)}</span></div>
        ${work.length ? `<div class="r">${ico('people')}<div><b>各组在做</b><ul>${work.slice(0, 6).map(x => `<li><span>${esc(x[0])}</span>${esc(x[1])}</li>`).join('')}</ul></div><span></span></div>` : ''}
        ${recent.length ? `<div class="r">${ico('alert', 'warn')}<div><b>最近 3 天</b><ul>${recent.map(r => `<li>${r.n ? rnHTML(r.n) + ' ' : ''}${esc(r.title.replace(/^#\d+\s*/, ''))}</li>`).join('')}</ul></div><span></span></div>` : ''}
        ${nextMs ? `<div class="r">${ico('flag')}<div><b>${esc(nextMs.label)}</b><p>下一个节点 · ${esc(fT(nextMs.a))}</p></div><span class="tag acc">还有 ${esc(F.dur(nextMs.a - t))}</span></div>` : ''}
      </div>`;
    $('ledgerNote').textContent = `${ev.slots.length} 个窗口，按上机顺序`;
    $('ledger').innerHTML = ev.slots.map(sl => {
      const ss = slotState(sl);
      let note;
      if (ss.k === 'empty') note = '赛前退出，空档作缓冲';
      else if (ss.k === 'wait') note = `${F.dt(sl.s)} 上机 · 还有 ${F.dur(sl.s - t)}${sl.delay ? `（比公布晚 ${F.dur(sl.delay)}）` : ''}`;
      else if (ss.k === 'p1') note = `${list(T1)} · ${F.dur(sl.p1 - t)}后转开发期`;
      else if (ss.k === 'dev') note = `${T2.length} 类应用并行 · ${F.dur(sl.seal - t)}后封存`;
      else if (ss.k === 'formal') note = `组委会运行正式评测 · ${F.dur(sl.e - t)}后下机`;
      else if (ss.k === 'out') note = `#${ss.out.n} 宕机 ${ss.out.hours} 小时${ss.out.comp ? '，补时' : ss.out.move ? '，剩余挪到补赛' : ''}`;
      else if (ss.k === 'mkwait') note = `剩余 ${sl.moved.remain} 小时，等补赛`;
      else if (ss.k === 'mk') note = `补赛中 · 剩余 ${sl.moved.remain} 小时`;
      else if (ss.k === 'quit') note = `第 ${sl.quit.at} 小时退出，剩余作废`;
      else note = `${F.dt(sl.e)} 下机${sl.makeup ? ` · 含补时 ${sl.makeup} 小时` : ''}`;
      const m = ev.mk.find(x => x.sl === sl);
      const c = sl.kind === 'empty' || t < sl.s ? 0 : m && t >= m.a ? sl.moved.from + Math.min(t, m.b) - m.a : clockOf(sl, Math.min(t, sl.e));
      const f1 = Math.max(0, Math.min(1, c / P.phase1)), f2 = Math.max(0, Math.min(1, (c - P.phase1) / (P.window - P.phase1)));
      const tc = tk => { const p1 = tk.phase === 1; if (ss.k === 'wait' || ss.k === 'empty') return 'todo'; if (ss.k === 'p1') return p1 ? 'live' : 'todo'; if (['dev', 'formal', 'mk'].includes(ss.k)) return p1 ? '' : 'live'; return ''; };
      const rs = R.flags.filter(f => f.team === sl.L && f.h <= t);
      const avc = ss.cls === 'active' ? 'on' : ss.cls === 'alarm' ? 'alarm' : '';
      const tagc = ss.cls === 'active' ? 'acc' : ss.cls === 'alarm' ? 'crit' : ss.k === 'done' ? 'good' : '';
      return `<div class="lr"><span class="av ${avc}">${esc(sl.who)}</span>
        <div><div class="nm">${esc(sl.who)} ${sl.kind === 'standby' ? `候补 <span class="tag">接 ${esc(sl.L)} 队</span>` : '队'}<span class="tag ${tagc}">${tagc ? '<i></i>' : ''}${esc(ss.pill)}</span></div><div class="nt">${esc(note)}</div>
          ${rs.length ? `<div class="rk">${rs.map(f => `<span class="tag ${f.sev === 'critical' ? 'crit' : 'warn'}">#${f.n} ${esc((R.risks[f.n - 1] || {}).effect || f.title)}</span>`).join('')}</div>` : ''}</div>
        <div class="prog"><div class="bar"><span style="flex:${P.phase1}"><i style="width:${f1 * 100}%"></i></span><span style="flex:${P.window - P.phase1}"><i style="width:${f2 * 100}%"></i></span></div><div class="chips">${TASKS.map(tk => tchip(tk, tc(tk))).join('')}</div></div>
        <div class="val">${sl.kind === 'empty' ? '—' : `${Math.min(P.window, c)}<small>/ ${P.window} h</small>`}</div></div>`;
    }).join('');
  }

  /* ---------- log ---------- */
  const LOGF = [['all', '全部'], ['risk', '风险与应对'], ['ms', '节点']];
  const KIND = {ms: ['flag', '', '节点'], act: ['dot', '', '进展'], risk: ['alert', 'crit', '风险'], resp: ['arrow', 'acc', '应对'], warn: ['alert', 'warn', '隐患'], info: ['info', '', '提示']};
  const logVisible = l => logFilter === 'risk' ? ['risk', 'resp', 'warn'].includes(l.kind) : logFilter === 'ms' ? (l.kind === 'ms' || l.kind === 'warn') : true;
  function renderLog(){
    $('logTabs').innerHTML = LOGF.map(x => `<button type="button" data-f="${x[0]}" aria-pressed="${logFilter === x[0]}">${x[1]}</button>`).join('');
    const rows = R.log.map((l, i) => ({l, i})).filter(x => logVisible(x.l));
    $('logTitle').textContent = `${rows.length} 条`;
    $('logList').innerHTML = rows.map(({l, i}) => {
      const k = KIND[l.kind] || KIND.info;
      const sev = l.n && R.risks[l.n - 1] ? R.risks[l.n - 1].def.sev : null;
      const icon = l.kind === 'risk' && sev ? `<span class="ic ${sev === 'critical' ? 'crit' : 'warn'}" style="font:600 10px var(--fm)">#${l.n}</span>` : ico(k[0], k[1]);
      return `<li class="le" data-i="${i}" data-h="${l.h}"><span class="le-t">${esc(fT(l.h))}</span>${icon}<div class="le-b"><b>${l.kind === 'risk' && l.n ? '' : ''}${esc(l.kind === 'risk' && l.n ? l.title.replace(/^#\d+\s*/, '') : l.title)}</b>${l.text ? `<p>${esc(l.text)}</p>` : ''}</div><span class="tag">${esc(k[2])}</span></li>`;
    }).join('') || '<li class="empty">没有符合筛选的条目。</li>';
    curLog = -2; markLog();
  }
  function markLog(){
    const els = $('logList').querySelectorAll('.le'); let cur = null;
    els.forEach(el => { const h = +el.dataset.h; el.classList.toggle('future', h > t); el.classList.remove('cur'); if (h <= t) cur = el; });
    if (cur){ cur.classList.add('cur'); const i = +cur.dataset.i; if (i !== curLog){ curLog = i; const box = $('logList'), top = cur.offsetTop - box.offsetTop; if (top < box.scrollTop + 8 || top > box.scrollTop + box.clientHeight - 60) box.scrollTop = Math.max(0, top - box.clientHeight / 3); } }
    else if (curLog !== -1){ curLog = -1; $('logList').scrollTop = 0; }
  }
  listen($('logTabs'), 'click', e => { const b = e.target.closest('button[data-f]'); if (!b) return; logFilter = b.dataset.f; renderLog(); });
  listen($('logList'), 'click', e => { const li = e.target.closest('.le'); if (!li) return; stop(); setT(Math.ceil(+li.dataset.h), true); });
  function renderResults(){
    const F = R.F;
    const ds = R.disputes.slice().sort((p, q) => q.star - p.star);
    $('disputes').innerHTML = ds.length ? ds.map(d => `<div class="al">${ico(d.star ? 'alert' : 'info', d.star ? 'crit' : 'warn')}<div><b>${d.star ? '★ ' : ''}${esc(d.name)}<span class="tag">${esc(d.area)}</span>${d.by.length ? `<span class="tag">${esc(d.by.join('、'))} 队</span>` : ''}</b><p>预防：${esc(d.prevent)}</p></div></div>`).join('') : `<p class="empty">这个情景没有推演出争执。</p>`;
    const ws = R.warns.map(w => ({t: w.name, p: (w.consequence || '') + (w.state === 'drop' ? '开赛后机器被占用，补不了。' : w.state === 'short' ? `练习期实际只有 ${F.days(w.leadGot)}。` : '')}));
    if (R.HM > P.gap) ws.push({t: `交接要 ${R.HM} 小时，间隔只有 ${P.gap} 小时`, p: `每次换队把下一队往后推 ${R.HM - P.gap} 小时，延误一路传到最后一队。`});
    if (R.metrics.over > 0) ws.push({t: `比公布的赛程晚 ${F.dur(R.metrics.over)}结束`, p: `${R.metrics.delayedN} 队晚开表，最多晚 ${F.dur(R.metrics.maxDelay)}${R.metrics.movedN ? `；${R.metrics.movedN} 队挪到补赛窗口` : ''}。`});
    const neg = R.prep.list.filter(x => x.slack != null && x.slack < 0 && x.durH > 0);
    if (neg.length && P.launch === 'gate') ws.push({t: `${neg.length} 项赛前任务赶不上原定开赛`, p: `${neg.slice(0, 5).map(x => shortLabel(x.name)).join('、')}${neg.length > 5 ? ' 等' : ''}，所以开赛推迟。`});
    const zero = R.prep.list.filter(x => x.slack != null && x.slack >= 0 && x.slack < 24 && x.durH > 0);
    if (zero.length) ws.push({t: `${zero.length} 项赛前任务余量不到 1 天`, p: `${zero.map(x => shortLabel(x.name)).join('、')}：再晚一天就会推迟开赛。`});
    if (R.metrics.prizeExt) ws.push({t: '奖金发放撞上春节', p: `顺延 ${F.days(R.metrics.prizeExt)}。预案 §3 提醒过：赛后计划和奖金发放要避开春节。`});
    $('warns').innerHTML = ws.length ? ws.map(w => `<div class="al">${ico('alert', 'warn')}<div><b>${esc(w.t)}</b>${w.p ? `<p>${esc(w.p)}</p>` : ''}</div></div>`).join('') : `<p class="empty">没有推演出隐患。</p>`;
  }

  /* ---------- schedule table ---------- */
  function renderSched(){
    const F = R.F, ev = R.event;
    $('schedHead').innerHTML = `<tr><th>队伍</th><th>上机</th><th>转开发期</th><th>封存</th><th>下机</th><th>补时</th><th>节假日</th><th>备注</th></tr>`;
    $('schedBody').innerHTML = ev.slots.map(sl => {
      const live = sl.kind !== 'empty' && t >= sl.s && t < sl.e, ss = slotState(sl);
      const notes = [];
      if (sl.kind === 'standby') notes.push(`候补，接 ${sl.L} 队`);
      if (sl.kind === 'empty') notes.push('赛前退出，空档作缓冲');
      if (sl.delay) notes.push(`比公布的 ${F.dt(sl.ann)} 晚 ${F.dur(sl.delay)}`);
      if (sl.quit) notes.push(`第 ${sl.quit.at} 小时退出`);
      if (sl.moved){ const m = ev.mk.find(x => x.sl === sl); notes.push(`剩余 ${sl.moved.remain} 小时 ${m ? F.dt(m.a) + ' 起补赛' : '挪到补赛'}`); }
      if (sl.standbyQ) notes.push('用备用题');
      if (sl.degraded) notes.push('条件不一致');
      if (sl.outs.length) notes.push(sl.outs.map(o => `#${o.n} 宕机 ${o.hours}h`).join('、'));
      const hs = sl.kind === 'empty' ? [] : R.holidays.filter(x => x.h < sl.e && x.h + 24 > sl.s).map(x => x.name);
      const avc = ss.cls === 'active' ? 'on' : ss.cls === 'alarm' ? 'alarm' : '';
      return `<tr class="${live ? 'live' : ''}"><td><span class="who"><span class="av ${avc}">${esc(sl.who)}</span>${sl.kind === 'standby' ? '候补' : '队'}</span></td>
        <td class="mono">${sl.kind === 'empty' ? '—' : esc(F.dt(sl.s))}</td><td class="mono">${sl.p1 != null ? esc(F.dt(sl.p1)) : '—'}</td><td class="mono">${sl.seal != null ? esc(F.dt(sl.seal)) : '—'}</td>
        <td class="mono">${sl.kind === 'empty' ? '—' : esc(F.dt(sl.e))}</td><td class="mono">${sl.makeup ? sl.makeup + ' h' : '—'}</td><td>${hs.length ? hs.map(h => `<span class="tag">${esc(h)}</span>`).join(' ') : '—'}</td><td class="wide">${esc(notes.join('；')) || '—'}</td></tr>`;
    }).join('');
    const M = R.metrics;
    $('schedNote').textContent = `每队 ${P.window} 小时，第 ${P.sealAt} 小时封存。换队留 ${P.gap} 小时，交接实际要 ${R.HM} 小时${R.plan === 'pause' ? '；节前停赛' : ''}。补赛窗口 ${P.makeupDays} 天。${M.over > 0 ? `最后一队比公布晚 ${F.dur(M.over)}。` : ''}`;
  }

  /* ---------- one team ---------- */
  function renderZoom(){
    const ev = R.event, F = R.F;
    $('ztabs').innerHTML = ev.slots.map((sl, i) => `<button type="button" aria-pressed="${i === sel}" data-i="${i}" ${sl.kind === 'empty' ? 'disabled' : ''} title="${esc(sl.kind === 'empty' ? sl.L + ' 队空档' : sl.who + ' 队')}">${esc(sl.who)}</button>`).join('');
    let sl = ev.slots[sel];
    if (!sl || sl.kind === 'empty'){ sel = Math.max(0, ev.slots.findIndex(x => x.kind !== 'empty')); sl = ev.slots[sel]; }
    if (!sl || sl.kind === 'empty'){ $('zoomTitle').textContent = '没有队伍上机。'; $('detailBox').innerHTML = ''; return; }
    const WIN = P.window, P1 = P.phase1, SP = P.sealAt, ss = slotState(sl);
    $('zoomNote').textContent = `${ev.played.length} 队的结构相同，只是日期依次后移。横轴是这一队自己的比赛时钟；平台故障补时期间时钟停走，所以补时的宕机画成一条细线。`;
    const mkSeg = ev.mk.find(m => m.sl === sl);
    const wallOf = c => mkSeg && c > sl.moved.from ? mkSeg.a + (c - sl.moved.from) : sl.wall(c);
    const stTxt = ss.k === 'wait' ? `等待上机，还有 ${F.dur(sl.s - t)}` : ['p1', 'dev', 'formal', 'out'].includes(ss.k) ? `进行中 · 第 ${clockOf(sl, t)} 小时` : ss.k === 'mk' ? '补赛中' : ss.k === 'mkwait' ? '等补赛' : ss.k === 'quit' ? '已退出' : '已完成';
    $('zoomTitle').textContent = `${sl.who} 队${sl.kind === 'standby' ? `（候补，接 ${sl.L} 队）` : ''} · ${stTxt}`;
    $('zoomSub').textContent = `${F.long(sl.s)} → ${F.long(sl.e)}${mkSeg ? `，补赛到 ${F.dt(mkSeg.b)}` : ''}`;
    const W = 1060, L = 236, Rr = 24, plotW = W - L - Rr, top = 60, lh = 46;
    const lanes = [...TASKS]; if (C.bonus) lanes.push({id: 'opt', en: C.bonus.en, zh: `${C.bonus.zh} · 可选，最高 +${C.bonus.max}`});
    const yb = top + lanes.length * lh, H = yb + 42, X = h => L + h / WIN * plotW;
    let s = `<svg class="detail" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(`${sl.who} 队 ${WIN} 小时窗口`)}">`;
    [[0, P1, `${PH[0].name} · 开卷`, ''], [P1, SP, '开发期', ''], [SP, WIN, '正式评测 · 组委会运行', 'f']].forEach(([p, q, nm, c]) => { const w = X(q) - X(p) - 3; s += `<rect class="band ${c}" x="${X(p) + 1.5}" y="6" width="${Math.max(1, w)}" height="24" rx="6"/>`; if (w > textW(nm, 11.5) + 14) s += `<text class="bn" x="${X(p) + 10}" y="22">${esc(nm)}</text>`; });
    const step = WIN <= 240 ? 24 : WIN <= 480 ? 48 : 96;
    const ticks = []; for (let h = 0; h <= WIN; h += step) ticks.push(h);
    if (ticks[ticks.length - 1] !== WIN){ if (X(WIN) - X(ticks[ticks.length - 1]) < 40) ticks.pop(); ticks.push(WIN); }
    ticks.forEach(h => { const anc = h === 0 ? 'start' : h === WIN ? 'end' : 'middle'; s += `<line class="tick" x1="${X(h)}" x2="${X(h)}" y1="${top - 6}" y2="${yb}"/><text class="tk" x="${X(h)}" y="${yb + 16}" text-anchor="${anc}">${h}h</text><text class="tkd" x="${X(h)}" y="${yb + 31}" text-anchor="${anc}">${sl.quit && h > sl.quit.at ? '' : esc(F.day(wallOf(Math.min(h, WIN))))}</text>`; });
    [P1, SP].forEach(h => { s += `<line class="tick p" x1="${X(h)}" x2="${X(h)}" y1="${top - 6}" y2="${yb}"/>`; });
    const inPlay = ['p1', 'dev', 'formal', 'out', 'mk'].includes(ss.k);
    const cNow = inPlay ? (ss.k === 'mk' ? sl.moved.from + (t - mkSeg.a) : clockOf(sl, t)) : ['done', 'quit'].includes(ss.k) ? (sl.quit ? sl.quit.at : WIN) : 0;
    lanes.forEach((tk, j) => {
      const cy = top + j * lh + lh / 2;
      if (tk.id === 'opt'){
        s += `<rect x="14" y="${cy - 12}" width="24" height="24" rx="7" fill="none" stroke="var(--line-2)" stroke-dasharray="3 3"/><use href="#i-opt" x="19" y="${cy - 7}" width="14" height="14" style="color:var(--muted)"/>`;
        s += `<text class="en" x="48" y="${cy - 2}">${esc(tk.en)}</text><text class="zh" x="48" y="${cy + 14}">${esc(tk.zh)}</text>`;
        s += `<rect class="opt" x="${X(P1) + 2}" y="${cy - 9}" width="${Math.max(0, X(WIN) - X(P1) - 4)}" height="18" rx="6"/>`;
        return;
      }
      s += `<rect x="14" y="${cy - 12}" width="24" height="24" rx="7" fill="var(--t-${tk.id}-bg)"/><use href="#i-${tk.icon}" x="19" y="${cy - 7}" width="14" height="14" style="color:var(--t-${tk.id})"/>`;
      s += `<text class="en" x="48" y="${cy - 2}">${esc(tk.en)}</text><text class="zh" x="48" y="${cy + 14}">${esc(tk.zh)} · ${tk.points || 0} 分</text>`;
      const [a, b] = tk.phase === 1 ? [0, P1] : [P1, WIN];
      s += `<rect class="trk" x="${X(a) + 1.5}" y="${cy - 8}" width="${Math.max(1, X(b) - X(a) - 3)}" height="16" rx="5"/>`;
      const fe = Math.min(b, Math.max(a, cNow));
      if (fe > a) s += `<rect class="b1" x="${X(a) + 1.5}" y="${cy - 8}" width="${Math.max(0, X(fe) - X(a) - 3)}" height="16" rx="5"/>`;
      if (tk.phase !== 1) s += `<line stroke="var(--surface)" stroke-width="2" x1="${X(SP)}" x2="${X(SP)}" y1="${cy - 8}" y2="${cy + 8}"/>`;
    });
    if (sl.quit){ s += `<rect class="x" x="${X(sl.quit.at)}" y="${top - 6}" width="${X(WIN) - X(sl.quit.at)}" height="${yb - top + 6}" opacity=".85"/><text class="xt" x="${X(sl.quit.at) + 8}" y="${top + 8}">退出 · 剩余 ${sl.quit.voidH} 小时作废</text>`; }
    if (sl.moved) s += `<text class="xt" x="${X(sl.moved.from) + 8}" y="${top + 8}">${mkSeg ? `之后的部分在补赛窗口完成（${F.dt(mkSeg.a)} 起）` : '剩余时间挪到补赛窗口'}</text>`;
    sl.outs.forEach(o => {
      const thin = o.comp || o.move || o.cause === 'degraded';
      s += thin ? `<rect class="o" x="${X(o.at) - 1.5}" y="${top - 6}" width="3" height="${yb - top + 6}" ${o.cause === 'degraded' ? 'style="fill:var(--warn)"' : ''}/>` : `<rect class="o" x="${X(o.at)}" y="${top - 6}" width="${Math.max(3, X(o.at + o.hours) - X(o.at))}" height="${yb - top + 6}" opacity=".5"/>`;
      s += `<text class="ot" x="${X(o.at) + 6}" y="${yb - 6}">#${o.n} 宕机 ${o.hours}h · ${o.move ? '挪补赛' : o.comp ? '补时' : o.cause === 'degraded' ? '降配' : '不补'}</text>`;
    });
    if (inPlay){
      const nx = X(Math.min(WIN, cNow)); s += `<line class="nl" x1="${nx}" x2="${nx}" y1="${top - 8}" y2="${yb}"/>`;
      const lab = `现在 ${Math.floor(cNow)}h`, lw = textW(lab, 10.5) + 16, lx = Math.min(Math.max(nx - lw / 2, L), W - Rr - lw);
      s += `<rect class="np" x="${lx}" y="${top - 28}" width="${lw}" height="18" rx="9"/><text class="npt" x="${lx + lw / 2}" y="${top - 15.5}" text-anchor="middle">${esc(lab)}</text>`;
    }
    s += `</svg>`;
    $('detailBox').innerHTML = s;
  }
  function renderCards(){
    $('cards').innerHTML = TASKS.map(tk => `<article class="card tcard">
      <div class="tcard-h">${tchip(tk, 'lg')}<div><b>${esc(tk.en)}</b><small>${esc(tk.zh)}</small></div></div>
      <div class="meta"><span>${tk.phase === 1 ? `${esc(PH[0].name)} · 0–${P.phase1}h` : `${esc(PH[1].name)} · ${P.phase1}–${P.window}h`}</span><b>${tk.points || 0} 分</b></div>
      <dl><div><dt>交付</dt><dd>${esc(tk.deliver)}</dd></div><div><dt>验收要点</dt><dd>${esc(tk.check)}</dd></div></dl>
    </article>`).join('');
  }
  listen($('ztabs'), 'click', e => { const b = e.target.closest('button[data-i]'); if (!b || b.disabled) return; sel = +b.dataset.i; if (view === 'in') renderEvent(); renderZoom(); });

  /* ---------- score ---------- */
  function renderScore(){
    const formal = TASKS.reduce((a, x) => a + (x.points || 0), 0), bonus = C.bonus ? C.bonus.max : 0, sp = C.appScore || [];
    $('scoreNote').textContent = `正式分 ${formal} 分，${TASKS.length} 个任务各 ${TASKS[0] ? TASKS[0].points : 25} 分；平台优化可选，最高再加 ${bonus} 分，总分最高 ${formal + bonus}。`;
    $('scoreCard').innerHTML = `<div class="alloc" role="img" aria-label="${esc(TASKS.map(x => `${x.en} ${x.points}`).join('、'))}">${TASKS.map(x => `<div class="t-${esc(x.id)}" style="flex:${x.points}"></div>`).join('')}${bonus ? `<div class="opt" style="flex:${bonus}"></div>` : ''}</div>
      <div class="arows">${TASKS.map(x => `<div class="ar">${tchip(x)}<div><b>${esc(x.en)}</b><small>${esc(x.zh)} · ${x.phase === 1 ? PH[0].name : PH[1].name}</small></div><span class="v">${x.points}<small>分</small></span></div>`).join('')}
        ${bonus ? `<div class="ar"><span class="tchip" style="background:transparent;border:1.5px dashed var(--line-2);color:var(--muted)"><svg><use href="#i-opt"/></svg></span><div><b>${esc(C.bonus.en)}</b><small>${esc(C.bonus.zh)} · 可选 · ${esc(C.bonus.note || '')}</small></div><span class="v">≤ ${bonus}<small>分</small></span></div>` : ''}</div>
      <div class="snotes">
        <div><h4>每类应用 ${sp.reduce((a, x) => a + x[1], 0)} 分的构成</h4><div class="split3">${sp.map(x => `<i style="flex:${x[1]}"></i>`).join('')}</div><p>${esc(sp.map(x => `${x[0]} ${x[1]} 分`).join(' · '))}。${esc(C.appScoreNote || '')}</p></div>
        <div><h4>两个阶段的工具边界</h4><p>${esc(PH[0].name)}（${esc(PH[0].tag)}）：${esc(PH[0].tools)}。${esc(PH[1].name)}：${esc(PH[1].tools)}。</p></div>
        <div><h4>团队大奖</h4><p class="prize">${esc(C.prize ? C.prize.amount : '')}</p><p>${esc(C.prize ? C.prize.count : '')} · ${esc(C.prize ? C.prize.note : '')}</p></div>
      </div>`;
  }

  /* ---------- prep table ---------- */
  function renderPrep(){
    const F = R.F, M = R.metrics;
    const rows = R.prep.list.slice().sort((p, q) => p.es - q.es || p.ef - q.ef);
    $('prepSum').textContent = `${P.scope === 'mvp' ? '最低可用版' : '完整版'} · ${rows.length} 项 · 关键路径 ${rows.filter(x => x.crit).length} 项`;
    $('prepNote').textContent = `工期是估计值，用 − / + 改，整条时间线马上重算。余量按原定 ${F.dateCN(M.planned)} 开赛倒推。`;
    const owner = id => ((C.lanes || []).find(l => l.id === id) || {}).owner || '';
    $('prepBody').innerHTML = rows.map(x => {
      const tags = [];
      if (x.crit) tags.push('<span class="tag acc"><i></i>关键路径</span>');
      if (x.gate) tags.push(`<span class="tag">${x.gate === 'hard' ? '门禁 · 必须' : '门禁'}</span>`);
      if (x.state === 'drop') tags.push('<span class="tag warn">没做完 · 机器被占</span>');
      if (x.state === 'late') tags.push('<span class="tag warn">开赛时没做完</span>');
      if (x.state === 'short') tags.push(`<span class="tag warn">练习期只有 ${esc(F.days(x.leadGot))}</span>`);
      (x.hits || []).forEach(r => tags.push(`<span class="tag crit">#${r.n} +${r.days} 天</span>`));
      const c = C.prep.find(c => c.id === x.id), def = P.scope === 'mvp' && c.mvp != null ? c.mvp : c.days;
      const chg = P.dur[x.id] != null && P.dur[x.id] !== def;
      const slack = x.slack == null ? '—' : x.slack < 0 ? `<span class="neg">${esc(F.days(x.slack))}</span>` : esc(F.days(x.slack));
      return `<tr><td>${esc(x.name)}</td><td class="wide" style="min-width:0">${esc(owner(x.lane))}</td><td><div class="stepper${chg ? ' chg' : ''}" data-d="${esc(x.id)}"><button type="button" data-s="-1" aria-label="减一天">−</button><input type="number" min="0" max="60" value="${x.base}" data-d="${esc(x.id)}" aria-label="${esc(x.name)} 工期（天）"><button type="button" data-s="1" aria-label="加一天">+</button></div></td><td class="mono">${esc(F.day(x.es))}</td><td class="mono">${esc(F.day(x.ef))}</td><td class="mono">${slack}</td><td>${tags.join(' ')}</td></tr>`;
    }).join('');
  }
  const setDur = (id, v) => { stop(); P.dur[id] = clampInt(v, 0, 60, 0); recompute(); };
  listen($('prepBody'), 'click', e => { const b = e.target.closest('.stepper button'); if (!b) return; const st = b.parentElement, id = st.dataset.d; setDur(id, +st.querySelector('input').value + (+b.dataset.s)); });
  listen($('prepBody'), 'change', e => { const el = e.target.closest('input[data-d]'); if (el) setDur(el.dataset.d, el.value); });
  listen($('durReset'), 'click', () => { stop(); P.dur = {}; recompute(); });

  /* ---------- register ---------- */
  function renderRegister(){
    const inj = new Map(); risks.forEach((r, i) => { if (!inj.has(r.type)) inj.set(r.type, []); inj.get(r.type).push(i + 1); });
    const order = ['pre', 'in', 'post'];
    const rows = C.register.slice().sort((p, q) => order.indexOf(p.stage) - order.indexOf(q.stage));
    $('regSum').textContent = `预案第 3–7 节共 ${rows.length} 项，其中 ${rows.filter(x => x.inject).length} 项可以注入推演${inj.size ? `；本次注入 ${rows.filter(x => x.inject && inj.has(x.inject)).length} 项` : ''}。`;
    $('regBody').innerHTML = rows.map(x => { const ns = x.inject && inj.get(x.inject); return `<tr class="${ns ? 'on' : ''}"><td><span class="tag">${STAGE[x.stage]}</span></td><td class="wide"><b>${esc(x.risk)}</b>${ns ? ` <span class="tag crit">#${ns.join(' #')}</span>` : ''}</td><td class="wide">${esc(x.resp)}</td><td class="wide">${esc(x.prep)}</td><td class="mono">${esc(x.ref)}</td><td>${x.inject ? `<button class="inj" type="button" data-inj="${esc(x.inject)}">＋ 注入</button>` : '<span class="lbl">只登记</span>'}</td></tr>`; }).join('');
  }
  listen($('regBody'), 'click', e => { const b = e.target.closest('[data-inj]'); if (!b) return; stop(); risks.push(mkRisk(b.dataset.inj)); presetId = '__custom'; recompute(); $('risks').scrollIntoView({behavior: reduced ? 'auto' : 'smooth', block: 'start'}); });

  function renderNotes(){
    $('notesList').innerHTML = (C.notes || []).map(n => `<li><b>${esc(n.kind)}：</b>${esc(n.text)}</li>`).join('') + `<li><b>当前推演参数：</b>${P.teams} 队，每队 ${P.window} 小时（第一阶段 ${P.phase1} 小时，第 ${P.sealAt} 小时封存），原定 ${esc(P.start)} ${pad(P.hour)}:00 开赛，换队间隔 ${P.gap} 小时，${P.scope === 'mvp' ? '最低可用版' : '完整版'} Benchmark，${P.launch === 'gate' ? '按启动门禁开赛' : '按日期硬开'}。</li>`;
    $('sourceNote').innerHTML = `赛制来源：${esc(C.source.label)}。预案：<code>${esc(C.doc)}</code>。默认场景在 <code>scenario.js</code>，推演规则在 <code>engine.js</code>；页面上调的参数和风险只做临时推演，刷新即回到默认。旧版保留在 <code>v1/</code>、<code>v2/</code>。`;
  }

  /* ---------- time ---------- */
  function setT(h, follow){
    t = Math.round(h);
    if (follow){ const v = stageOf(t); if (v !== view){ view = v; renderVTabs(); renderBoard(); } }
    renderTime();
  }
  function renderTime(){
    const [a, z] = domainOf(view), sc = $('scrub');
    sc.min = a; sc.max = z; sc.value = Math.max(a, Math.min(z, t));
    sc.style.setProperty('--p', ((Math.max(a, Math.min(z, t)) - a) / (z - a) * 100) + '%');
    $('scrubT').textContent = fT(t);
    if (view === 'in') renderEvent(); else drawPlayhead();
    placeLifePh(); renderNow(); markLog(); renderSched(); renderZoom();
  }
  function renderAll(){
    renderOverview(); renderRisks(); renderLife(); renderVTabs(); renderBoard();
    renderLog(); renderResults(); renderCards(); renderScore(); renderPrep(); renderRegister(); renderNotes();
    renderTime();
  }
  listen($('scrub'), 'input', () => { stop(); setT(+$('scrub').value, false); });

  /* ---------- pointer on chart ---------- */
  const tip = $('tip');
  let dragging = false, lastType = 'mouse';
  const svgPt = e => { const svg = $('ganttBox').querySelector('svg'); if (!svg || !GX) return null; const rc = svg.getBoundingClientRect(); return {x: (e.clientX - rc.left) / rc.width * GX.W, y: (e.clientY - rc.top) / rc.height * GX.H}; };
  function fromPointer(e){
    const p = svgPt(e); if (!p) return;
    if (p.x < GX.L - 4){
      if (GX.kind === 'in' && !dragging){ const row = Math.floor((p.y - GX.top + 4) / GX.rowH); if (row >= 0 && row < R.event.slots.length && R.event.slots[row].kind !== 'empty'){ sel = row; renderEvent(); renderZoom(); $('team').scrollIntoView({behavior: reduced ? 'auto' : 'smooth', block: 'start'}); } }
      return;
    }
    stop(); const k = (GX.X(GX.A + 24) - GX.X(GX.A)) / 24;
    setT(Math.max(GX.A, Math.min(GX.Z, GX.A + (p.x - GX.L) / k)), false);
  }
  listen($('ganttBox'), 'pointerdown', e => { lastType = e.pointerType; if (e.pointerType !== 'mouse' || e.button !== 0) return; const p = svgPt(e); if (!p || p.x < GX.L - 4) return; dragging = true; $('ganttBox').setPointerCapture(e.pointerId); tip.hidden = true; fromPointer(e); });
  listen($('ganttBox'), 'pointermove', e => { if (dragging){ fromPointer(e); return; } showTip(e); });
  listen($('ganttBox'), 'pointerup', () => { dragging = false; });
  listen($('ganttBox'), 'pointerleave', () => { if (!dragging) tip.hidden = true; });
  listen($('ganttBox'), 'click', e => { if (lastType === 'mouse'){ const p = svgPt(e); if (p && p.x < GX.L - 4) fromPointer(e); return; } fromPointer(e); });
  ['detailBox', 'strip'].forEach(id => { listen($(id), 'pointermove', showTip); listen($(id), 'pointerleave', () => { tip.hidden = true; }); });
  function showTip(e){
    const el = e.target.closest && e.target.closest('[data-tip],[title]');
    const txt = el && (el.getAttribute('data-tip') || el.getAttribute('title'));
    if (txt && e.pointerType === 'mouse'){
      tip.textContent = txt; tip.hidden = false;
      const tw = tip.offsetWidth, th = tip.offsetHeight;
      let x = e.clientX + 14, y = e.clientY + 16;
      if (x + tw > innerWidth - 8) x = e.clientX - tw - 14;
      if (y + th > innerHeight - 8) y = e.clientY - th - 12;
      tip.style.left = x + 'px'; tip.style.top = y + 'px';
    } else tip.hidden = true;
  }

  /* ---------- play ---------- */
  const playBtn = $('play');
  function setPlayUI(){ playBtn.innerHTML = `<svg><use href="#i-${playing ? 'pause' : 'play'}"/></svg><span>${playing ? '暂停' : '播放'}</span>`; }
  function stop(){ if (!playing) return; playing = false; cancelAnimationFrame(raf); setPlayUI(); }
  const SECS = {pre: 10, in: 18, post: 10};
  listen(playBtn, 'click', () => {
    if (playing){ stop(); return; }
    const [L0, L1] = life();
    if (t >= L1) setT(L0, true);
    playing = true; setPlayUI();
    let last = performance.now(), acc = t, lastDraw = 0;
    const tick = now => {
      if (!playing) return;
      const [a, z] = domainOf(view);
      acc += (now - last) / 1000 * ((z - a) / SECS[view]); last = now;
      if (acc >= L1){ setT(L1, true); playing = false; setPlayUI(); return; }
      if (now - lastDraw > 50){ setT(Math.floor(acc), true); lastDraw = now; }
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
  });

  /* ---------- scroll spy ---------- */
  (function spy(){
    const links = [...root.querySelectorAll('#nav a[data-s]')];
    const secs = links.map(a => root.querySelector('#' + a.dataset.s)).filter(Boolean);
    if (!('IntersectionObserver' in window)) return;
    const io = observer = new IntersectionObserver(es => { es.forEach(en => { if (en.isIntersecting){ links.forEach(a => a.classList.toggle('on', a.dataset.s === en.target.id)); } }); }, {rootMargin: '-30% 0px -60% 0px'});
    secs.forEach(s => io.observe(s));
    links[0] && links[0].classList.add('on');
  })();

  /* ---------- boot ---------- */
  R = ENG.simulate(C, P, []); B = R;
  t = Math.max(R.stages[0].a, Math.min(R.stages[2].b, Math.round(todayH())));
  view = stageOf(t);
  syncInputs();
  recompute();
return () => { stop(); events.abort(); observer?.disconnect(); };
}